/**
 * GitHub Workflow 文件内容（内嵌为字符串，用于站点同步时推送到用户仓库）
 *
 * 为什么把 YAML 内嵌为字符串？
 * - 站点同步是在浏览器端运行的，浏览器读不了本地 .github/ 目录的文件
 * - 同步时把这个字符串以 file content 的形式提交到 GitHub API
 * - 路径是 .github/workflows/inquiry-notification.yml
 * - 只有 .github/workflows/ 目录下的 YAML 文件才会被 GitHub Actions 识别
 *
 * 注意：此文件内容必须与 .github/workflows/inquiry-notification.yml 保持一致
 * 修改 workflow 逻辑时，两个地方都要改
 */

// EXPORTS: INQUIRY_NOTIFICATION_WORKFLOW_PATH, INQUIRY_NOTIFICATION_WORKFLOW_CONTENT

export const INQUIRY_NOTIFICATION_WORKFLOW_PATH = '.github/workflows/inquiry-notification.yml';

export const INQUIRY_NOTIFICATION_WORKFLOW_CONTENT = `name: Inquiry Email Notification

# 询盘邮件通知工作流
# 当新 Issue 被创建且标题包含 "[Inquiry]" 时，自动发送邮件通知
#
# 🔴 触发方式（双重保险）：
#   1. issues.opened + 标题以 "[Inquiry]" 开头 → 主要触发路径
#   2. issues.labeled + label 是 "inquiry" → 兜底触发路径
#   为什么要双触发？
#   - 如果 labels 创建失败（422 错误），标题前缀路径仍能触发
#   - 如果标题前缀判断有问题，labels 路径仍能触发
#   - 去重：labeled 事件只在标题不以 [Inquiry] 开头时才执行，避免重复发送
#
# 配置步骤：
# 1. 在仓库 Settings → Secrets and variables → Actions 中添加以下 Secrets：
#    - SMTP_SERVER: SMTP 服务器地址（如 smtp.gmail.com）
#    - SMTP_PORT: SMTP 端口（如 465 或 587）
#    - SMTP_USERNAME: SMTP 用户名（如 your-email@gmail.com）
#    - SMTP_PASSWORD: SMTP 密码/应用专用密码
#    - NOTIFY_EMAIL: 接收询盘通知的邮箱
#    - SENDER_EMAIL: 发件人邮箱（可选，默认使用 SMTP_USERNAME）
# 2. 确保 Personal Access Token 有 "Issues" 读写权限
# 3. 前端提交询盘时会自动创建标题以 "[Inquiry]" 开头的 Issue，触发此 workflow
# 4. 用后台 "Test Issue Creation" 按钮测试时，标题为 "[Inquiry] [Test] ..."，
#    同样会触发邮件通知（这样可以验证整条链路是否通畅）

on:
  issues:
    types: [opened, labeled]

jobs:
  send-inquiry-email:
    name: Send Inquiry Email
    runs-on: ubuntu-latest
    # 触发条件：
    #   - opened 事件：标题以 [Inquiry] 开头（主路径）
    #   - labeled 事件：标签是 "inquiry" 且标题不以 [Inquiry] 开头（兜底）
    if: |
      (github.event.action == 'opened' && startsWith(github.event.issue.title, '[Inquiry]')) ||
      (github.event.action == 'labeled' && github.event.label.name == 'inquiry' && !startsWith(github.event.issue.title, '[Inquiry]'))
    steps:
      - name: Debug — issue and event info
        id: debug
        run: |
          echo "=== Issue Details ==="
          echo "Event action: \${{ github.event.action }}"
          echo "Issue title: \${{ github.event.issue.title }}"
          echo "Issue number: \${{ github.event.issue.number }}"
          echo "Issue URL: \${{ github.event.issue.html_url }}"
          echo "Issue state: \${{ github.event.issue.state }}"
          echo "Created at: \${{ github.event.issue.created_at }}"
          echo "Labels: \${{ join(github.event.issue.labels.*.name, ', ') }}"
          if [ "\${{ github.event.action }}" = "labeled" ]; then
            echo "Label that triggered: \${{ github.event.label.name }}"
          fi
          echo "===================="
          echo ""
           echo "Secrets availability (set / not set):"
           [ -n "\${{ secrets.SMTP_SERVER }}" ]   && echo "  SMTP_SERVER:   SET"   || echo "  SMTP_SERVER:   NOT SET"
           [ -n "\${{ secrets.SMTP_PORT }}" ]     && echo "  SMTP_PORT:     SET"   || echo "  SMTP_PORT:     NOT SET"
           [ -n "\${{ secrets.SMTP_USERNAME }}" ] && echo "  SMTP_USERNAME: SET"   || echo "  SMTP_USERNAME: NOT SET"
           [ -n "\${{ secrets.SMTP_PASSWORD }}" ] && echo "  SMTP_PASSWORD: SET"   || echo "  SMTP_PASSWORD: NOT SET"
           [ -n "\${{ secrets.NOTIFY_EMAIL }}" ]  && echo "  NOTIFY_EMAIL:  SET"   || echo "  NOTIFY_EMAIL:  NOT SET"
           [ -n "\${{ secrets.SENDER_EMAIL }}" ]  && echo "  SENDER_EMAIL:  SET"   || echo "  SENDER_EMAIL:  NOT SET"
          echo ""
          echo "Trigger info:"
          echo "  action=opened, title starts with [Inquiry]: \${{ github.event.action == 'opened' && startsWith(github.event.issue.title, '[Inquiry]') }}"
          echo "  action=labeled, label=inquiry, no title match: \${{ github.event.action == 'labeled' && github.event.label.name == 'inquiry' && !startsWith(github.event.issue.title, '[Inquiry]') }}"

      - name: Validate required secrets
        id: validate
        run: |
          MISSING=""
          [ -z "\${{ secrets.SMTP_SERVER }}" ]   && MISSING="\$MISSING SMTP_SERVER"
          [ -z "\${{ secrets.SMTP_PORT }}" ]     && MISSING="\$MISSING SMTP_PORT"
          [ -z "\${{ secrets.SMTP_USERNAME }}" ] && MISSING="\$MISSING SMTP_USERNAME"
          [ -z "\${{ secrets.SMTP_PASSWORD }}" ] && MISSING="\$MISSING SMTP_PASSWORD"
          [ -z "\${{ secrets.NOTIFY_EMAIL }}" ]  && MISSING="\$MISSING NOTIFY_EMAIL"

          if [ -n "\$MISSING" ]; then
            echo "::error::Missing required secrets:\$MISSING"
            echo "::warning::Go to Settings → Secrets and variables → Actions and add the missing secrets."
            echo "HAS_REQUIRED_SECRETS=false" >> \$GITHUB_OUTPUT
          else
            echo "All required secrets are configured."
            echo "HAS_REQUIRED_SECRETS=true" >> \$GITHUB_OUTPUT
          fi

      - name: Send email notification
        id: send_email
        if: steps.validate.outputs.HAS_REQUIRED_SECRETS == 'true'
        uses: dawidd6/action-send-mail@v3
        with:
          server_address: \${{ secrets.SMTP_SERVER }}
          server_port: \${{ secrets.SMTP_PORT }}
          username: \${{ secrets.SMTP_USERNAME }}
          password: \${{ secrets.SMTP_PASSWORD }}
          from: \${{ secrets.SENDER_EMAIL || secrets.SMTP_USERNAME }}
          to: \${{ secrets.NOTIFY_EMAIL }}
          subject: "[New Inquiry] \${{ github.event.issue.title }}"
          body: |
            A new inquiry has been submitted on your website.

            --------------------------------------------------

            \${{ github.event.issue.body }}

            --------------------------------------------------

            📋 Issue Details:
            • Title: \${{ github.event.issue.title }}
            • Number: #\${{ github.event.issue.number }}
            • URL: \${{ github.event.issue.html_url }}
            • Submitted at: \${{ github.event.issue.created_at }}
            • Labels: \${{ join(github.event.issue.labels.*.name, ', ') || '(none)' }}
            • Trigger: \${{ github.event.action }} event

            --
            This is an automated notification from GitHub Actions (inquiry-notification workflow).
            To stop these emails, remove or disable the .github/workflows/inquiry-notification.yml file.
          priority: high

      - name: Success summary
        if: success()
        run: |
          echo "✅ Email notification sent successfully"
          echo "Issue: #\${{ github.event.issue.number }} — \${{ github.event.issue.title }}"
          echo "URL: \${{ github.event.issue.html_url }}"
          echo "Recipient: \${{ secrets.NOTIFY_EMAIL }}"

      - name: Failure troubleshooting
        if: failure()
        run: |
          echo "❌ Email notification FAILED"
          echo "Issue: #\${{ github.event.issue.number }} — \${{ github.event.issue.title }}"
          echo ""
          echo "===== Troubleshooting Guide ====="
          echo ""
          echo "1. Check all Secrets are configured in:"
          echo "   Settings → Secrets and variables → Actions → Repository secrets"
          echo ""
          echo "   Required secrets:"
          echo "   • SMTP_SERVER   - SMTP server (e.g. smtp.gmail.com)"
          echo "   • SMTP_PORT     - SMTP port (465 for SSL, 587 for STARTTLS)"
          echo "   • SMTP_USERNAME - SMTP login (your full email)"
          echo "   • SMTP_PASSWORD - SMTP password or app password"
          echo "   • NOTIFY_EMAIL  - Recipient email address"
          echo ""
          echo "2. Gmail users: You MUST use an 'App Password', NOT your regular password."
          echo "   - Enable 2-Step Verification first"
          echo "   - Create app password at https://myaccount.google.com/apppasswords"
          echo "   - Use that 16-character code as SMTP_PASSWORD"
          echo ""
          echo "3. Try different port numbers:"
          echo "   • Port 465 — SSL/TLS (most common for dawidd6/action-send-mail)"
          echo "   • Port 587 — STARTTLS"
          echo ""
          echo "4. Verify the sender email matches SMTP_USERNAME"
          echo "   - If SENDER_EMAIL is set, make sure it matches SMTP_USERNAME"
          echo "   - Most SMTP servers require sender = authenticated user"
          echo ""
          echo "5. Check if your email provider has rate limits or blocks new IPs"
          echo "   - Gmail may flag the first send as suspicious"
          echo "   - Check your spam folder for any bounce-back emails"
          echo ""
          echo "6. Secrets are case-sensitive and must not have leading/trailing spaces"
`;
