export interface SyncModuleDefinition {
  key: SyncModuleKey;
  label: string;
  /** 收集阶段：返回处理后的数据（图片字段已替换为 GitHub 路径）和待上传文件列表 */
  collectFn: () => Promise<{ data: unknown; files: PendingFile[] }>;
  /** 提交成功后的 Storage 优化（用 GitHub 路径替换本地 base64） */
  onSuccess?: () => Promise<void> | void;
}

export interface PendingFile {
  path: string;      // 仓库内路径，如 data/products.json
  content: string;   // 内容，文本或 base64
  isBase64: boolean; // 是否为 base64 编码（图片）
}

export interface SiteSyncProgress {
  currentIndex: number;
  total: number;
  currentLabel: string;
  successCount: number;
  errorCount: number;
  errors: { module: string; label: string; message: string }[];
  isSyncing: boolean;
  /** 当前阶段：collecting 收集文件 / committing 批量提交 / optimizing Storage 优化 */
  phase?: 'collecting' | 'committing' | 'optimizing' | 'done';
}

export interface SyncAllOptions {
  onProgress?: (progress: SiteSyncProgress) => void;
  onModuleDone?: (label: string, success: boolean, errorMsg?: string) => void;
  onComplete?: (result: {
    successCount: number;
    errorCount: number;
    errors: { module: string; label: string; message: string }[];
  }) => void;
}

/**
 * 深拷贝数据（JSON 序列化，适合普通对象）
 */
function deepClone<T>(obj: T): T {
  return JSON.parse(JSON.stringify(obj));
}

/**
 * 从 base64 图片数组中提取纯 base64（去掉 data:... 前缀），用于去重
 */
function extractPureBase64(dataUrl: string): string {
  const idx = dataUrl.indexOf(',');
  return idx >= 0 ? dataUrl.slice(idx + 1) : dataUrl;
}

/**
 * 在数据中递归查找 base64 图片，生成待上传文件，并替换数据中的路径
 * 返回处理后的数据和待上传文件列表
 *
 * 注意：不实际上传，只收集。上传在批量提交阶段统一完成。
 */
function collectImagesInData<T>(
  data: T,
  moduleDir: string,
  imageFields: (keyof T)[],
  uploadedCache: Map<string, string>
): { data: T; files: PendingFile[] } {
  const files: PendingFile[] = [];

  const uploadOne = (dataUrl: string): string => {
    const pure = extractPureBase64(dataUrl);
    const cached = uploadedCache.get(pure);
    if (cached) {
      return cached;
    }
    const targetPath = generateImageFilename('image.jpg', moduleDir);
    const { base64 } = extractBase64FromDataUrl(dataUrl);
    files.push({ path: targetPath, content: base64, isBase64: true });
    uploadedCache.set(pure, targetPath);
    return targetPath;
  };

  const processImageField = (obj: Record<string, unknown>, field: string) => {
    const val = obj[field];
    if (typeof val === 'string' && isLocalBase64Image(val)) {
      const targetPath = uploadOne(val);
      obj[field] = `/${targetPath}`;
    }
  };

  const processGalleryField = (obj: Record<string, unknown>, field: string) => {
    const val = obj[field];
    if (field === 'gallery' && Array.isArray(val)) {
      const newGallery: string[] = [];
      for (const img of val) {
        if (typeof img === 'string' && isLocalBase64Image(img)) {
          const targetPath = uploadOne(img);
          newGallery.push(`/${targetPath}`);
        } else if (typeof img === 'string') {
          newGallery.push(img);
        }
      }
      obj[field] = newGallery;
    }
  };

  if (!Array.isArray(data)) {
    const obj = { ...(data as Record<string, unknown>) } as Record<string, unknown>;
    for (const field of imageFields as string[]) {
      processImageField(obj, field);
      processGalleryField(obj, field);
    }
    // image 与 gallery[0] 去重
    const imgVal = obj['image'];
    const galVal = obj['gallery'];
    if (
      typeof imgVal === 'string' &&
      imgVal.startsWith('/') &&
      Array.isArray(galVal) &&
      galVal[0] &&
      typeof galVal[0] === 'string' &&
      galVal[0].startsWith('/') &&
      imgVal !== galVal[0] &&
      isLocalBase64Image((data as Record<string, unknown>)['image'] as string) &&
      isLocalBase64Image(((data as Record<string, unknown>)['gallery'] as string[])[0] || '')
    ) {
      const origImg = (data as Record<string, unknown>)['image'] as string;
      const origGal0 = ((data as Record<string, unknown>)['gallery'] as string[])[0] || '';
      if (extractPureBase64(origImg) === extractPureBase64(origGal0)) {
        obj['image'] = galVal[0];
      }
    }
    return { data: obj as T, files };
  }

  const result: unknown[] = [];
  for (const item of data as unknown[]) {
    if (!item || typeof item !== 'object') {
      result.push(item);
      continue;
    }
    const obj = { ...(item as Record<string, unknown>) } as Record<string, unknown>;
    for (const field of imageFields as string[]) {
      processImageField(obj, field);
      processGalleryField(obj, field);
    }
    // image 与 gallery[0] 去重
    const imgVal = obj['image'];
    const galVal = obj['gallery'];
    const origItem = item as Record<string, unknown>;
    const origImg = typeof origItem['image'] === 'string' ? origItem['image'] : '';
    const origGalArr = Array.isArray(origItem['gallery']) ? (origItem['gallery'] as string[]) : [];
    const origGal0 = origGalArr[0] || '';
    if (
      typeof imgVal === 'string' &&
      imgVal.startsWith('/') &&
      Array.isArray(galVal) &&
      galVal[0] &&
      typeof galVal[0] === 'string' &&
      galVal[0].startsWith('/') &&
      isLocalBase64Image(origImg) &&
      isLocalBase64Image(origGal0) &&
      extractPureBase64(origImg) === extractPureBase64(origGal0)
    ) {
      obj['image'] = galVal[0];
    }
    result.push(obj);
  }

  return { data: result as unknown as T, files };
}

/**
 * 处理单个 base64 图片字段：生成待上传文件，返回 GitHub 路径
 */
function collectSingleImage(
  dataUrl: string,
  filename: string,
  moduleDir: string,
  files: PendingFile[],
  uploadedCache: Map<string, string>
): string {
  const pure = extractPureBase64(dataUrl);
  const cached = uploadedCache.get(pure);
  if (cached) {
    return `/${cached}`;
  }
  const targetPath = generateImageFilename(filename, moduleDir);
  const { base64 } = extractBase64FromDataUrl(dataUrl);
  files.push({ path: targetPath, content: base64, isBase64: true });
  uploadedCache.set(pure, targetPath);
  return `/${targetPath}`;
}

export function useSiteWideSync() {
  const { getGithubApiConfig, markSyncing, markSynced, markError } = useSyncService();
  const { products, updateProductsWithGithubPaths } = useProducts();
  const { advantages } = useAdvantages();
  const { testimonials, saveTestimonials, showOnHomepage, setShowOnHomepage } = useTestimonials();
  const { features, sectionImage, saveFeatures, setFeatureSectionImage } = useFeatures();
  const { slides, saveSlides } = useHeroSlides();
  const { content: aboutContent, saveContent } = useAboutContent();
  const { articles, saveArticles } = useNews();
  const { categories, saveCategories } = useCategories();
  const { settings: footerSettings, updateSettings: updateFooterSettings } = useFooterSettings();
  const { settings: seoSettings, saveSettings: saveSeoSettings } = useSeoSettings();
  const { config: githubConfig } = useGithubConfig();
  const { data: privacyData } = usePrivacyPolicy();
  const { getAllTranslations } = useI18n();
  const { inquiries } = useInquiries();

  const syncAll = useCallback(
    async (options?: SyncAllOptions) => {
      const config = getGithubApiConfig();
      if (!config) {
        options?.onComplete?.({
          successCount: 0,
          errorCount: 1,
          errors: [
            {
              module: 'all',
              label: 'All',
              message:
                'GitHub sync not configured. Go to GitHub Sync settings to set up your repository.',
            },
          ],
        });
        return {
          successCount: 0,
          errorCount: 1,
          errors: [
            {
              module: 'all',
              label: 'All',
              message:
                'GitHub sync not configured. Go to GitHub Sync settings to set up your repository.',
            },
          ],
        };
      }

      // 全局图片去重缓存
      const uploadedCache = new Map<string, string>();
      // 收集到的所有待提交文件
      const allFiles: PendingFile[] = [];
      // 各模块处理后的数据（用于提交成功后的 Storage 优化）
      const moduleResults = new Map<string, unknown>();

      const modules: SyncModuleDefinition[] = [
        {
          key: 'products',
          label: 'Products',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              products,
              'products',
              ['image' as any, 'gallery' as any],
              uploadedCache
            );
            const jsonPath = 'data/products.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: async () => {
            const dataWithImages = moduleResults.get('products') as typeof products;
            if (dataWithImages) {
              try {
                await updateProductsWithGithubPaths(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save products after sync:', String(e));
              }
            }
          },
        },
        {
          key: 'advantages',
          label: 'Advantages',
          collectFn: async () => {
            const jsonPath = 'data/advantages.json';
            const jsonContent = JSON.stringify(advantages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            return { data: advantages, files: [] };
          },
        },
        {
          key: 'testimonials',
          label: 'Testimonials',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              testimonials,
              'testimonials',
              ['avatar' as any],
              uploadedCache
            );
            const jsonPath = 'data/testimonials.json';
            // 包装成对象，带上 showOnHomepage 总开关；老数据读取时保持兼容
            const payload = { showOnHomepage, data: dataWithImages };
            const jsonContent = JSON.stringify(payload, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: payload, files };
          },
          onSuccess: () => {
            const result = moduleResults.get('testimonials') as
              | { showOnHomepage?: boolean; data: typeof testimonials }
              | typeof testimonials;
            if (result) {
              try {
                // 兼容两种格式：对象包装 or 纯数组
                if (Array.isArray(result)) {
                  saveTestimonials(result);
                } else if (Array.isArray(result.data)) {
                  saveTestimonials(result.data);
                  if (typeof result.showOnHomepage === 'boolean') {
                    setShowOnHomepage(result.showOnHomepage);
                  }
                }
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save testimonials:', String(e));
              }
            }
          },
        },
        {
          key: 'quoteSection',
          label: 'Quote Section',
          collectFn: async () => {
            // 直接从 localStorage 读取最新数据
            let data: unknown = null;
            try {
              const saved = localStorage.getItem('__app_ledlight_quote_section_v1');
              if (saved) {
                const parsed = JSON.parse(saved);
                data = parsed.data ?? null;
              }
            } catch {
              // ignore
            }
            const jsonPath = 'data/quote-section.json';
            const jsonContent = JSON.stringify(data, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            return { data, files: [] };
          },
          onSuccess: () => {
            const result = moduleResults.get('quoteSection');
            if (result && typeof result === 'object' && !Array.isArray(result)) {
              try {
                // 触发自定义事件，让 useQuoteSection 内部监听刷新
                window.dispatchEvent(new CustomEvent('app-ledlight-quote-section-github-pulled'));
              } catch (e) {
                logger.warn('[SiteSync] Failed to refresh quote section:', String(e));
              }
            }
          },
        },
        {
          key: 'faqs',
          label: 'FAQs',
          collectFn: async () => {
            const { scopedStorage } = await import('@lark-apaas/client-toolkit-lite');
            let faqsData: unknown[] = [];
            try {
              const raw = scopedStorage.getItem('__app_ledlight_faqs_v1');
              if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed.data && Array.isArray(parsed.data)) {
                  faqsData = parsed.data;
                }
              }
            } catch (e) {
              logger.warn('[SiteSync] Failed to read FAQs:', String(e));
            }
            const jsonPath = 'data/faqs.json';
            const jsonContent = JSON.stringify(faqsData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            logger.info(`[SiteSync] FAQs queued: ${faqsData.length} items`);
            return { data: faqsData, files: [] };
          },
        },
        {
          key: 'features',
          label: 'Features',
          collectFn: async () => {
            const files: PendingFile[] = [];
            const { data: featuresWithImages, files: iconFiles } = collectImagesInData(
              features,
              'features',
              ['icon' as any],
              uploadedCache
            );
            files.push(...iconFiles);
            const payload: Record<string, unknown> = { features: featuresWithImages };
            let finalSectionImage = sectionImage;
            if (sectionImage && typeof sectionImage === 'string' && isLocalBase64Image(sectionImage)) {
              finalSectionImage = collectSingleImage(
                sectionImage,
                'section-image.jpg',
                'features',
                files,
                uploadedCache
              );
              payload.sectionImage = finalSectionImage;
            } else if (sectionImage) {
              payload.sectionImage = sectionImage;
            }
            const jsonPath = 'data/features.json';
            const jsonContent = JSON.stringify(payload, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            moduleResults.set('features_sectionImage', finalSectionImage);
            return { data: payload, files };
          },
          onSuccess: () => {
            const payload = moduleResults.get('features') as Record<string, unknown>;
            const featuresData = payload?.features as typeof features;
            const finalSectionImage = moduleResults.get('features_sectionImage') as string;
            if (featuresData) {
              try {
                saveFeatures(featuresData);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save features:', String(e));
              }
            }
            if (finalSectionImage && finalSectionImage !== sectionImage) {
              try {
                setFeatureSectionImage(finalSectionImage);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save features section image:', String(e));
              }
            }
          },
        },
        {
          key: 'heroSlides',
          label: 'Hero Slides',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              slides,
              'hero-slides',
              ['image' as any],
              uploadedCache
            );
            const jsonPath = 'data/hero-slides.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: () => {
            const dataWithImages = moduleResults.get('heroSlides') as typeof slides;
            if (dataWithImages) {
              try {
                saveSlides(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save hero slides:', String(e));
              }
            }
          },
        },
        {
          key: 'about',
          label: 'About Page',
          collectFn: async () => {
            const files: PendingFile[] = [];
            const aboutData = deepClone(aboutContent) as unknown as Record<string, unknown>;
            if (aboutData.heroImage && isLocalBase64Image(aboutData.heroImage as string)) {
              aboutData.heroImage = collectSingleImage(
                aboutData.heroImage as string,
                'about-hero.jpg',
                'about',
                files,
                uploadedCache
              );
            }
            if (Array.isArray(aboutData.gallery)) {
              for (const img of aboutData.gallery as Record<string, unknown>[]) {
                if (img.image && isLocalBase64Image(img.image as string)) {
                  img.image = collectSingleImage(
                    img.image as string,
                    'gallery.jpg',
                    'about/gallery',
                    files,
                    uploadedCache
                  );
                }
              }
            }
            if (Array.isArray(aboutData.certifications)) {
              for (const cert of aboutData.certifications as Record<string, unknown>[]) {
                if (cert.image && isLocalBase64Image(cert.image as string)) {
                  cert.image = collectSingleImage(
                    cert.image as string,
                    'cert.jpg',
                    'about/certifications',
                    files,
                    uploadedCache
                  );
                }
              }
            }
            const jsonPath = 'data/about.json';
            const jsonContent = JSON.stringify(aboutData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: aboutData, files };
          },
          onSuccess: () => {
            const aboutData = moduleResults.get('about') as typeof aboutContent;
            if (aboutData) {
              try {
                saveContent(aboutData);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save about content:', String(e));
              }
            }
          },
        },
        {
          key: 'news',
          label: 'News / Articles',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              articles,
              'news',
              ['coverImage' as any],
              uploadedCache
            );
            const jsonPath = 'data/news.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: () => {
            const dataWithImages = moduleResults.get('news') as typeof articles;
            if (dataWithImages) {
              try {
                saveArticles(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save news:', String(e));
              }
            }
          },
        },
        {
          key: 'categories',
          label: 'Product Categories',
          collectFn: async () => {
            const { data: dataWithImages, files } = collectImagesInData(
              categories,
              'categories',
              ['iconImage' as any],
              uploadedCache
            );
            const jsonPath = 'data/categories.json';
            const jsonContent = JSON.stringify(dataWithImages, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: dataWithImages, files };
          },
          onSuccess: () => {
            const dataWithImages = moduleResults.get('categories') as typeof categories;
            if (dataWithImages) {
              try {
                saveCategories(dataWithImages);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save categories:', String(e));
              }
            }
          },
        },
        {
          key: 'footer',
          label: 'Footer / Header Settings',
          collectFn: async () => {
            const files: PendingFile[] = [];
            const data = deepClone(footerSettings) as unknown as Record<string, unknown>;
            if (data.footerLogo && isLocalBase64Image(data.footerLogo as string)) {
              data.footerLogo = collectSingleImage(
                data.footerLogo as string,
                'footer-logo.png',
                'footer',
                files,
                uploadedCache
              );
            }
            if (data.headerLogo && isLocalBase64Image(data.headerLogo as string)) {
              data.headerLogo = collectSingleImage(
                data.headerLogo as string,
                'header-logo.png',
                'footer',
                files,
                uploadedCache
              );
            }
            if (data.wechatQrImage && isLocalBase64Image(data.wechatQrImage as string)) {
              data.wechatQrImage = collectSingleImage(
                data.wechatQrImage as string,
                'wechat-qr.png',
                'footer',
                files,
                uploadedCache
              );
            }
            const jsonPath = 'data/footer.json';
            const jsonContent = JSON.stringify(data, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data, files };
          },
          onSuccess: () => {
            const data = moduleResults.get('footer') as Record<string, unknown>;
            if (data) {
              try {
                updateFooterSettings(data);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save footer settings:', String(e));
              }
            }
          },
        },
        {
          key: 'seo',
          label: 'SEO Settings',
          collectFn: async () => {
            const files: PendingFile[] = [];
            const seoData = deepClone(seoSettings) as unknown as Record<string, unknown>;
            const globalSettings = seoData.global as Record<string, unknown> | undefined;
            if (
              globalSettings &&
              globalSettings.ogImage &&
              typeof globalSettings.ogImage === 'string' &&
              isLocalBase64Image(globalSettings.ogImage)
            ) {
              globalSettings.ogImage = collectSingleImage(
                globalSettings.ogImage,
                'og-image.jpg',
                'seo',
                files,
                uploadedCache
              );
            }
            const jsonPath = 'data/seo.json';
            const jsonContent = JSON.stringify(seoData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...files);
            return { data: seoData, files };
          },
          onSuccess: () => {
            const seoData = moduleResults.get('seo') as typeof seoSettings;
            if (seoData) {
              try {
                saveSeoSettings(seoData as any);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save SEO settings:', String(e));
              }
            }
          },
        },
        {
          key: 'privacy',
          label: 'Privacy Policy',
          collectFn: async () => {
            const jsonPath = 'data/privacy.json';
            const jsonContent = JSON.stringify(privacyData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            return { data: privacyData, files: [] };
          },
        },
        {
          key: 'settings',
          label: 'Site Settings',
          collectFn: async () => {
            // 收集系统设置：管理员密码 + 分析设置 + 翻译设置 + GitHub 配置
            // 密码存入 data/settings.json，实现跨浏览器同步和部署包升级后不丢失
            // ⚠️ 注意：如果仓库是 Public 的，密码会公开可见，请自行评估风险
            const analyticsSettings = loadAnalyticsSettings();
            const fullTranslate = getTranslateSettings();
            // 翻译设置：只保留非敏感字段
            const safeTranslation = {
              provider: fullTranslate.provider,
              deeplPlan: fullTranslate.deeplPlan,
              useCorsProxy: fullTranslate.useCorsProxy,
              customProxyUrl: fullTranslate.customProxyUrl,
            };
            // GitHub 配置：只保留非敏感字段（token 剥离）
            const safeGithubSync = {
              owner: githubConfig.owner,
              repo: githubConfig.repo,
              branch: githubConfig.branch,
              basePath: githubConfig.basePath,
              enabled: githubConfig.enabled,
              workerUrl: githubConfig.workerUrl || '',
            };
            // 管理员密码：从 localStorage 读取，加密后写入 settings.json
            // 采用简单 XOR + Base64 加密，避免明文存在公开仓库
            let adminPassword = 'admin123';
            try {
              const saved = localStorage.getItem('__app_ledlight_admin_password');
              if (saved && typeof saved === 'string' && saved.length >= 6) {
                adminPassword = saved;
              }
            } catch {
              // ignore
            }
            const { encryptPassword } = await import('@/lib/password-crypto');
            const encryptedPassword = encryptPassword(adminPassword);
            const settingsData = {
              adminPassword: encryptedPassword,
              analytics: analyticsSettings,
              translation: safeTranslation,
              githubSync: safeGithubSync,
              updatedAt: Date.now(),
            };
            const jsonPath = 'data/settings.json';
            const jsonContent = JSON.stringify(settingsData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            return { data: settingsData, files: [] };
          },
          onSuccess: async () => {
            const data = moduleResults.get('settings') as Record<string, unknown> | undefined;
            if (!data) return;
            // 管理员密码：从远端同步回写（加密存储，解密后存入本地）
            // 🔴 重要：如果本地已有非默认密码（用户改过），不被远程覆盖，保证密码永久固定
            if (data.adminPassword && typeof data.adminPassword === 'string' && data.adminPassword.length >= 6) {
              try {
                // 先检查本地密码是否已被用户修改
                let localPwd = 'admin123';
                try {
                  const saved = localStorage.getItem('__app_ledlight_admin_password');
                  if (saved && typeof saved === 'string' && saved.length >= 6) {
                    localPwd = saved;
                  }
                } catch {
                  // ignore
                }

                const { decryptPassword } = await import('@/lib/password-crypto');
                const decrypted = decryptPassword(data.adminPassword);
                const remotePwd = decrypted && decrypted.length >= 6 ? decrypted : data.adminPassword;

                // 只有当本地是默认密码时，才用远程密码覆盖
                if (localPwd === 'admin123') {
                  localStorage.setItem('__app_ledlight_admin_password', remotePwd);
                  logger.info(`[SiteWideSync] Synced admin password from remote (local was default)`);
                } else {
                  logger.info(`[SiteWideSync] Skipped password overwrite — local password is customized, preserving user change`);
                }
              } catch {
                // ignore
              }
            }
            // 分析设置
            if (data.analytics && typeof data.analytics === 'object') {
              try {
                const analyticsSettings = data.analytics as Record<string, unknown>;
                const analyticsKey = '__app_ledlight_analytics_settings';
                localStorage.setItem(analyticsKey, JSON.stringify(analyticsSettings));
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save analytics settings:', String(e));
              }
            }
            // 翻译设置：合并非敏感字段（保留本地已有的 API Key 等敏感字段）
            if (data.translation && typeof data.translation === 'object') {
              try {
                const remote = data.translation as Record<string, unknown>;
                const local = getTranslateSettings();
                const merged: typeof local = {
                  ...local,
                  provider: (remote.provider as 'deepl' | 'mymemory') ?? local.provider,
                  deeplPlan: (remote.deeplPlan as 'free' | 'pro') ?? local.deeplPlan,
                  useCorsProxy: typeof remote.useCorsProxy === 'boolean' ? remote.useCorsProxy : local.useCorsProxy,
                  customProxyUrl: typeof remote.customProxyUrl === 'string' ? remote.customProxyUrl : local.customProxyUrl,
                };
                saveTranslateSettings(merged);
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save translation settings:', String(e));
              }
            }
            // GitHub 配置：合并非敏感字段（保留本地 token）
            if (data.githubSync && typeof data.githubSync === 'object') {
              try {
                const remote = data.githubSync as Record<string, unknown>;
                const githubKey = '__app_ledlight_github_config_v1';
                const saved = localStorage.getItem(githubKey);
                const local = saved ? JSON.parse(saved) : {};
                const merged = {
                  ...local,
                  owner: typeof remote.owner === 'string' ? remote.owner : local.owner ?? '',
                  repo: typeof remote.repo === 'string' ? remote.repo : local.repo ?? '',
                  branch: typeof remote.branch === 'string' ? remote.branch : local.branch ?? 'main',
                  basePath: typeof remote.basePath === 'string' ? remote.basePath : local.basePath ?? '',
                  enabled: typeof remote.enabled === 'boolean' ? remote.enabled : (local.enabled ?? false),
                  workerUrl: typeof remote.workerUrl === 'string' ? remote.workerUrl : local.workerUrl ?? '',
                };
                localStorage.setItem(githubKey, JSON.stringify(merged));
                // 触发同 tab 刷新事件
                try {
                  window.dispatchEvent(
                    new CustomEvent('github-config-change', { detail: merged })
                  );
                } catch {
                  /* ignore */
                }
              } catch (e) {
                logger.warn('[Storage-optimize] Failed to save GitHub config:', String(e));
              }
            }
          },
        },
        {
          key: 'translations',
          label: 'Translations',
          collectFn: async () => {
            // 收集所有翻译数据（默认值 + 用户自定义覆盖），完整写入 data/translations.json
            // 这样上传新部署包后，远程 data/translations.json 仍然存在，翻译不会丢失
            const allTranslations = getAllTranslations();
            const jsonPath = 'data/translations.json';
            const jsonContent = JSON.stringify(allTranslations, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            return { data: allTranslations, files: [] };
          },
        },
        {
          key: 'inquiries',
          label: 'Inquiries',
          collectFn: async () => {
            // 把本地询盘数据同步到 GitHub 的 data/inquiries.json
            // 这样不同浏览器打开后台都能看到所有询盘
            const jsonPath = 'data/inquiries.json';
            const jsonContent = JSON.stringify(inquiries, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            logger.info(
              `[SiteSync] Inquiries queued: ${inquiries.length} total inquiries`
            );
            return { data: inquiries, files: [] };
          },
        },
        {
          key: 'factoryVideo',
          label: 'Factory Video',
          collectFn: async () => {
            // 收集工厂视频设置 + 视频文件
            // 设置存 data/factory-video.json，视频文件存 files/factory-video-home.mp4 / about.mp4
            const { scopedStorage } = await import('@lark-apaas/client-toolkit-lite');

            // 读取设置
            let settingsData: Record<string, unknown> = {};
            try {
              const raw = scopedStorage.getItem('__app_ledlight_factory_video_settings');
              if (raw) {
                const parsed = JSON.parse(raw);
                if (parsed.data && typeof parsed.data === 'object') {
                  settingsData = parsed.data as Record<string, unknown>;
                }
              }
            } catch (e) {
              logger.warn('[SiteSync] Failed to read factory video settings:', String(e));
            }

            // 读取视频文件（IndexedDB）
            const videoFiles: PendingFile[] = [];
            try {
              const { getFactoryVideoBlob, arrayBufferToBase64 } = await import('@/hooks/useFactoryVideo');
              for (const target of ['home', 'about'] as const) {
                const blob = await getFactoryVideoBlob(target);
                if (blob && blob.size > 0) {
                  const arrayBuffer = await blob.arrayBuffer();
                  const base64 = arrayBufferToBase64(arrayBuffer);
                  const ext = settingsData[`${target}VideoName`]
                    ? String(settingsData[`${target}VideoName`]).split('.').pop() || 'mp4'
                    : 'mp4';
                  const filePath = `files/factory-video-${target}.${ext}`;
                  videoFiles.push({ path: filePath, content: base64, isBase64: true });
                  // 更新 settings 中的 URL 为 GitHub 路径
                  settingsData[`${target}VideoUrl`] = `/${filePath}`;
                }
              }
            } catch (e) {
              logger.warn('[SiteSync] Failed to collect factory video files:', String(e));
            }

            settingsData.updatedAt = Date.now();
            const jsonPath = 'data/factory-video.json';
            const jsonContent = JSON.stringify(settingsData, null, 2);
            allFiles.push({ path: jsonPath, content: jsonContent, isBase64: false });
            allFiles.push(...videoFiles);

            logger.info(
              `[SiteSync] Factory video queued: ${videoFiles.length} video file(s)`
            );
            return { data: settingsData, files: videoFiles };
          },
        },
        {
          key: 'workflows',
          label: 'GitHub Workflows',
          collectFn: async () => {
            // 把 GitHub Actions workflow 文件推送到仓库
            // 这是询盘邮件通知的基础设施，只有放在 .github/workflows/ 下才会生效
            allFiles.push({
              path: INQUIRY_NOTIFICATION_WORKFLOW_PATH,
              content: INQUIRY_NOTIFICATION_WORKFLOW_CONTENT,
              isBase64: false,
            });
            logger.info(
              `[SiteSync] Workflow file queued: ${INQUIRY_NOTIFICATION_WORKFLOW_PATH} ` +
              `(${INQUIRY_NOTIFICATION_WORKFLOW_CONTENT.length} chars)`
            );
            return { data: { workflows: ['inquiry-notification'] }, files: [] };
          },
        },
      ];

      const total = modules.length;
      let successCount = 0;
      let errorCount = 0;
      const errors: { module: string; label: string; message: string }[] = [];

      // ========== 阶段 1：收集所有文件 ==========
      options?.onProgress?.({
        currentIndex: 0,
        total,
        currentLabel: 'Preparing files...',
        successCount: 0,
        errorCount: 0,
        errors: [],
        isSyncing: true,
        phase: 'collecting',
      });

      for (let i = 0; i < modules.length; i++) {
        const mod = modules[i];
        options?.onProgress?.({
          currentIndex: i,
          total,
          currentLabel: mod.label,
          successCount,
          errorCount,
          errors,
          isSyncing: true,
          phase: 'collecting',
        });

        markSyncing(mod.key);

        try {
          const { data } = await mod.collectFn();
          moduleResults.set(mod.key, data);
          markSynced(mod.key);
          successCount += 1;
          options?.onModuleDone?.(mod.label, true, '');
        } catch (err) {
          markError(mod.key);
          errorCount += 1;
          const msg = err instanceof Error ? err.message : String(err) || 'Unknown error';
          errors.push({ module: mod.key, label: mod.label, message: msg });
          options?.onModuleDone?.(mod.label, false, msg);
          logger.error(`[SiteSync] collect failed: ${mod.label}, error: ${msg}`);
        }
      }

      // ========== 阶段 2：批量提交 ==========
      if (errorCount > 0 && allFiles.length === 0) {
        // 完全没有可提交的文件，直接结束
        options?.onProgress?.({
          currentIndex: total,
          total,
          currentLabel: 'All done (with errors)',
          successCount,
          errorCount,
          errors,
          isSyncing: false,
          phase: 'done',
        });
        options?.onComplete?.({ successCount, errorCount, errors });
        return { successCount, errorCount, errors };
      }

      options?.onProgress?.({
        currentIndex: total,
        total,
        currentLabel: `Uploading ${allFiles.length} files (batch commit)...`,
        successCount,
        errorCount,
        errors,
        isSyncing: true,
        phase: 'committing',
      });

      logger.info(`[SiteSync] batch commit: ${allFiles.length} files total`);

      try {
        const moduleLabels = modules
          .filter((m) => !errors.some((e) => e.module === m.key))
          .map((m) => m.label.replace(/\s+/g, '-').toLowerCase())
          .join(', ');
        const commitMsg = `Sync site content: ${moduleLabels || 'site data'}`;

        const result = await createOrUpdateFilesBatch(
          config as GithubConfig,
          allFiles,
          commitMsg
        );

        logger.info(
          `[SiteSync] batch commit success: ${result.fileCount} files, commit=${result.commitSha.slice(
            0,
            7
          )}`
        );
      } catch (batchErr) {
        // 批量提交失败 — 所有模块标记为 error
        const batchMsg =
          batchErr instanceof Error ? batchErr.message : String(batchErr) || 'Batch commit failed';
        logger.error(`[SiteSync] batch commit failed: ${batchMsg}`);

        // 标记所有成功收集的模块为 error 状态
        for (const mod of modules) {
          if (!errors.some((e) => e.module === mod.key)) {
            markError(mod.key);
            errors.push({ module: mod.key, label: mod.label, message: batchMsg });
          }
        }
        errorCount = modules.length;
        successCount = 0;

        options?.onProgress?.({
          currentIndex: total,
          total,
          currentLabel: 'Batch commit failed',
          successCount,
          errorCount,
          errors,
          isSyncing: false,
          phase: 'done',
        });
        options?.onComplete?.({ successCount, errorCount, errors });
        return { successCount, errorCount, errors };
      }

      // ========== 阶段 3：Storage 优化（用 GitHub 路径替换本地 base64） ==========
      options?.onProgress?.({
        currentIndex: total,
        total,
        currentLabel: 'Optimizing local storage...',
        successCount,
        errorCount,
        errors,
        isSyncing: true,
        phase: 'optimizing',
      });

      for (const mod of modules) {
        if (errors.some((e) => e.module === mod.key)) continue;
        try {
          await mod.onSuccess?.();
        } catch (e) {
          logger.warn(`[Storage-optimize] ${mod.label}: ${String(e)}`);
        }
      }

      // ========== 完成 ==========
      options?.onProgress?.({
        currentIndex: total,
        total,
        currentLabel: 'All done',
        successCount,
        errorCount,
        errors,
        isSyncing: false,
        phase: 'done',
      });

      options?.onComplete?.({ successCount, errorCount, errors });

      return { successCount, errorCount, errors };
    },
    [
      getGithubApiConfig,
      markSyncing,
      markSynced,
      markError,
      products,
      updateProductsWithGithubPaths,
      advantages,
      testimonials,
      saveTestimonials,
      features,
      sectionImage,
      saveFeatures,
      setFeatureSectionImage,
      slides,
      saveSlides,
      aboutContent,
      saveContent,
      articles,
      saveArticles,
      categories,
      saveCategories,
      footerSettings,
      updateFooterSettings,
      seoSettings,
      saveSeoSettings,
      privacyData,
      inquiries,
    ]
  );

  return { syncAll };
}

export default useSiteWideSync;
