/**
 * GitHub 同步设置页面
 * 配置 Personal Access Token、仓库信息、分支等
 */

import { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent, CardFooter } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import { Badge } from '@/components/ui/badge';
import {
  Github,
  KeyRound,
  Server,
  GitBranch,
  Link2,
  CheckCircle2,
  XCircle,
  HelpCircle,
  ExternalLink,
  Eye,
  EyeOff,
  RefreshCw,
  AlertTriangle,
  UploadCloud,
  Loader2,
  MinusCircle,
  Clock,
  Mail,
   Sparkles,
   ArrowDownToLine,
   Globe,
   Shield,
  } from 'lucide-react';
import { useGithubConfig } from '@/hooks/useGithubConfig';
import { useSyncService } from '@/context/SyncServiceContext';
import { cn } from '@/lib/utils';
import { DATA_FILES } from '@/hooks/useGithubPullData';
import { useSiteWideSync, type SiteSyncProgress } from '@/hooks/useSiteWideSync';
import { useGithubPullData } from '@/hooks/useGithubPullData';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { toast } from 'sonner';
import { Separator } from '@/components/ui/separator';
import { useI18n } from '@/i18n/I18nContext';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { createIssue } from '@/lib/github-api';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';

export default function AdminGithubSyncPage() {
  const { adminT } = useI18n();
  const { markDirty } = useSyncService();
  const { config, saveConfig, testing, connectionStatus, connectionMessage, testGithubConnection } =
    useGithubConfig();
  const { syncAll } = useSiteWideSync();
  const pullData = useGithubPullData();
  const [showToken, setShowToken] = useState(false);
  const [localConfig, setLocalConfig] = useState(config);
  const [syncProgress, setSyncProgress] = useState<SiteSyncProgress | null>(null);
  const [syncFinished, setSyncFinished] = useState(false);
  const [testingIssue, setTestingIssue] = useState(false);
  const [issueTestResult, setIssueTestResult] = useState<{ success: boolean; message: string; issueUrl?: string } | null>(null);

  // 全局 config 变化时同步到 localConfig（比如从其他页面返回、或 Context 重新初始化）
  useEffect(() => {
    setLocalConfig(config);
  }, [config]);

  const handleChange = (field: string, value: string | boolean) => {
    setLocalConfig((prev) => ({ ...prev, [field]: value }));
  };

  const handleSave = () => {
    saveConfig(localConfig);
    markDirty('settings');
    toast.success(adminT('admin.githubSync.configSaved'));
  };

  const handleTest = async () => {
    // 先保存配置到 Context/localStorage
    saveConfig(localConfig);
    // 直接用 localConfig 调用 Context 的测试方法（表单里的当前值，包括 workerUrl）
    await testGithubConnection({
      token: localConfig.token.trim(),
      owner: localConfig.owner.trim(),
      repo: localConfig.repo.trim(),
      branch: localConfig.branch.trim(),
      basePath: localConfig.basePath,
      workerUrl: localConfig.workerUrl || '',
    });
  };

  // 测试 Issue 创建权限
  const handleTestIssue = async () => {
    saveConfig(localConfig);
    const token = localConfig.token.trim();
    const owner = localConfig.owner.trim();
    const repo = localConfig.repo.trim();
    const useWorker = !!(localConfig.workerUrl && localConfig.workerUrl.trim());

    if ((!token && !useWorker) || !owner || !repo) {
      toast.error(useWorker ? 'Please fill in Owner and Repository.' : 'Please fill in Token, Owner and Repository first');
      return;
    }

    setTestingIssue(true);
    setIssueTestResult(null);

    try {
       const result = await createIssue(
         // 🔴 测试 Issue 强制直连模式，与前台询盘实际行为一致
         // 前台询盘不走 Worker，所以测试也应该用直连模式验证
         { token, owner, repo, branch: localConfig.branch.trim(), basePath: localConfig.basePath || '', workerUrl: undefined },
        '[Inquiry] [Test] Notification Test',
        '## Test Inquiry\n\nThis is a **test inquiry** created from the admin panel to verify that the GitHub Issues + Email Notification setup is working correctly.\n\nIf you received an email notification for this issue, your setup is working correctly. ✅\n\n### What this test verifies:\n- GitHub Token has Issues write permission\n- Issue title starts with `[Inquiry]` (triggers the workflow)\n- GitHub Actions workflow is present and enabled\n- SMTP email sending is configured correctly\n\nYou can safely close this issue.',
        ['inquiry', 'test']
      );

      if (result.success) {
        // 测试成功后自动启用同步（否则测试通过了但实际询盘不同步）
        if (!localConfig.enabled) {
          saveConfig({ ...localConfig, enabled: true });
        } else {
          saveConfig(localConfig);
        }
        setIssueTestResult({
          success: true,
          message: `Issue created successfully! #${result.issueNumber} — your token has Issues write permission.${!localConfig.enabled ? ' GitHub sync has been auto-enabled.' : ''}`,
          issueUrl: result.issueUrl,
        });
        toast.success('Issue test passed!' + (!localConfig.enabled ? ' GitHub sync enabled.' : ''));
      } else {
        setIssueTestResult({
          success: false,
          message: result.message || 'Failed to create test issue.',
        });
        toast.error('Issue test failed');
      }
    } catch (err) {
      setIssueTestResult({
        success: false,
        message: err instanceof Error ? err.message : String(err),
      });
      toast.error('Issue test error');
    } finally {
      setTestingIssue(false);
    }
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.githubSync.title') }]}
      />

      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Github className="size-6" />
            {adminT('admin.githubSync.title')}
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            {adminT('admin.githubSync.subtitle')}
          </p>
        </div>
        <div className="flex items-center gap-2">
          {connectionStatus === 'success' && (
            <Badge variant="outline" className="bg-emerald-500/10 text-emerald-500 border-emerald-500/20">
              <CheckCircle2 className="size-3 mr-1" />
              {adminT('admin.githubSync.connected')}
            </Badge>
          )}
          {connectionStatus === 'error' && (
            <Badge variant="outline" className="bg-destructive/10 text-destructive border-destructive/20">
              <XCircle className="size-3 mr-1" />
              {adminT('admin.githubSync.connectionFailed')}
            </Badge>
          )}
        </div>
      </div>

      {/* 启用开关 */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Switch
              checked={localConfig.enabled}
              onCheckedChange={(v) => handleChange('enabled', v)}
            />
            {adminT('admin.githubSync.enable')}
          </CardTitle>
          <CardDescription>
            {adminT('admin.githubSync.enableDesc')}
          </CardDescription>
        </CardHeader>
      </Card>

      {/* 配置表单 */}
      <Card>
        <CardHeader>
          <CardTitle>{adminT('admin.githubSync.repoConfig')}</CardTitle>
          <CardDescription>
            {adminT('admin.githubSync.repoConfigDesc')}
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-5">
          {/* Cloudflare Worker 代理地址 */}
          <div className="space-y-2">
            <Label htmlFor="worker-url" className="flex items-center gap-2">
              <Globe className="size-4" />
              Cloudflare Worker URL <span className="text-xs text-muted-foreground">(推荐)</span>
            </Label>
            <Input
              id="worker-url"
              type="url"
              value={localConfig.workerUrl || ''}
              onChange={(e) => handleChange('workerUrl', e.target.value)}
              placeholder="https://your-worker.yourname.workers.dev"
            />
            <p className="text-xs text-muted-foreground">
              配置后，所有 GitHub API 调用通过 Cloudflare Worker 代理，GitHub Token 存储在 Worker Secrets 中，前端不保存敏感信息。
            </p>
            <div className="bg-primary/10 border border-primary/30 rounded-sm px-3 py-2 text-xs space-y-1">
              <p className="font-medium text-primary flex items-center gap-1.5">
                <Shield className="size-3.5" />
                Recommended for Public Repositories
              </p>
              <p className="text-muted-foreground">
                如果你的仓库是公开的 (Public)，强烈建议使用 Worker 代理模式。Token 只存在 Cloudflare Worker Secrets 中，不会出现在浏览器或 GitHub 仓库里。
              </p>
            </div>
          </div>

          <div className="relative">
            <div className="absolute inset-0 flex items-center">
              <Separator className="w-full" />
            </div>
            <div className="relative flex justify-center">
              <span className="bg-card px-3 text-xs text-muted-foreground">
                {localConfig.workerUrl ? 'Worker 模式（无需 Token）' : 'Direct Mode (requires Token)'}
              </span>
            </div>
          </div>

          {/* Personal Access Token —— 仅在未配置 Worker 时显示 */}
          {!localConfig.workerUrl && (
          <div className="space-y-2">
            <Label htmlFor="token" className="flex items-center gap-2">
              <KeyRound className="size-4" />
              {adminT('admin.githubSync.token')}
            </Label>
            <div className="relative">
              <Input
                id="token"
                type={showToken ? 'text' : 'password'}
                value={localConfig.token}
                onChange={(e) => handleChange('token', e.target.value)}
                 placeholder={adminT('admin.githubSync.tokenPlaceholder')}
                className="pr-10"
              />
              <Button
                type="button"
                variant="ghost"
                size="icon"
                className="absolute right-1 top-1/2 -translate-y-1/2 size-8"
                onClick={() => setShowToken(!showToken)}
              >
                {showToken ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
              </Button>
            </div>
              <p className="text-xs text-muted-foreground">
                {adminT('admin.githubSync.tokenHint')}
              </p>
              <div className="bg-amber-500/10 border border-amber-500/30 rounded-sm px-3 py-2 text-xs space-y-1">
                <p className="font-medium text-amber-600 dark:text-amber-500 flex items-center gap-1.5">
                  <AlertTriangle className="size-3.5" />
                  Issues Permission Required
                </p>
                <p className="text-muted-foreground">
                  For inquiry email notifications to work, your Fine-grained Token must have <strong>Issues: Read and write</strong> permission.
                  Use the "Test Issue Creation" button below to verify.
                </p>
              </div>
          </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="owner" className="flex items-center gap-2">
                <Server className="size-4" />
                 {adminT('admin.githubSync.owner')}
               </Label>
               <Input
                 id="owner"
                 value={localConfig.owner}
                 onChange={(e) => handleChange('owner', e.target.value)}
                 placeholder={adminT('admin.githubSync.ownerPlaceholder')}
               />
             </div>
             <div className="space-y-2">
               <Label htmlFor="repo" className="flex items-center gap-2">
                 <Github className="size-4" />
                 {adminT('admin.githubSync.repoName')}
               </Label>
               <Input
                 id="repo"
                 value={localConfig.repo}
                 onChange={(e) => handleChange('repo', e.target.value)}
                 placeholder={adminT('admin.githubSync.repoPlaceholder')}
               />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="branch" className="flex items-center gap-2">
                <GitBranch className="size-4" />
                 {adminT('admin.githubSync.branch')}
               </Label>
               <Input
                 id="branch"
                 value={localConfig.branch}
                 onChange={(e) => handleChange('branch', e.target.value)}
                 placeholder={adminT('admin.githubSync.branchPlaceholder')}
               />
               <p className="text-xs text-muted-foreground">
                 {adminT('admin.githubSync.branchHint')}
               </p>
            </div>
            <div className="space-y-2">
              <Label htmlFor="basePath" className="flex items-center gap-2">
                <Link2 className="size-4" />
                 {adminT('admin.githubSync.basePath')}
               </Label>
               <Input
                 id="basePath"
                 value={localConfig.basePath}
                 onChange={(e) => handleChange('basePath', e.target.value)}
                 placeholder={adminT('admin.githubSync.basePathPlaceholder')}
               />
               <p className="text-xs text-muted-foreground">
                 {adminT('admin.githubSync.basePathHint')}
               </p>
            </div>
          </div>
        </CardContent>
        <CardFooter className="flex flex-col sm:flex-row justify-between gap-3">
          <div className="flex gap-2">
            <Button variant="outline" onClick={handleTest} disabled={testing || testingIssue}>
              {testing ? (
                <RefreshCw className="size-4 mr-2 animate-spin" />
              ) : null}
              {testing ? adminT('admin.githubSync.testing') : adminT('admin.githubSync.testConnection')}
            </Button>
            <Button
              variant="secondary"
              onClick={handleTestIssue}
              disabled={testing || testingIssue}
              className="gap-2"
            >
              {testingIssue ? <RefreshCw className="size-4 animate-spin" /> : <Mail className="size-4" />}
              {testingIssue ? 'Testing...' : 'Test Issue Creation'}
            </Button>
          </div>
          <Button onClick={handleSave} disabled={testing || testingIssue}>
            {adminT('admin.githubSync.saveConfig')}
          </Button>
        </CardFooter>
      </Card>

      {/* 连接状态详情 */}
      {connectionMessage && (
        <Card className={
          connectionStatus === 'success'
            ? 'border-emerald-500/30 bg-emerald-500/5'
            : 'border-destructive/30 bg-destructive/5'
        }>
          <CardContent className="pt-6">
            <div className="flex items-center gap-3">
              {connectionStatus === 'success' ? (
                <CheckCircle2 className="size-6 text-emerald-500 shrink-0" />
              ) : (
                <XCircle className="size-6 text-destructive shrink-0" />
              )}
              <p className="text-sm">{connectionMessage}</p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* 一键同步全站 */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <UploadCloud className="size-5" />
             {adminT('admin.githubSync.syncAll')}
           </CardTitle>
           <CardDescription>
             {adminT('admin.githubSync.syncAllDesc')}
           </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {syncProgress ? (
            <div className="space-y-3">
              <div className="flex items-center justify-between text-sm">
                 <span className="text-foreground font-medium">
                   {syncProgress.isSyncing ? adminT('admin.githubSync.syncing') : syncFinished ? adminT('admin.githubSync.syncComplete') : adminT('admin.githubSync.preparing')}
                 </span>
                <span className="text-muted-foreground tabular-nums">
                  {syncProgress.currentIndex} / {syncProgress.total}
                </span>
              </div>
              {/* 进度条 */}
              <div className="w-full h-2 bg-border rounded-full overflow-hidden">
                <div
                  className="h-full bg-primary transition-all duration-300 ease-out"
                  style={{ width: `${(syncProgress.currentIndex / syncProgress.total) * 100}%` }}
                />
              </div>
              {/* 当前模块 */}
              {syncProgress.isSyncing && (
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Loader2 className="size-4 animate-spin text-primary" />
                   <span>{adminT('admin.githubSync.syncing')} {syncProgress.currentLabel}...</span>
                </div>
              )}
              {/* 完成统计 */}
              {syncFinished && (
                <div className="flex flex-wrap gap-4 text-sm pt-2">
                  <div className="flex items-center gap-1.5 text-emerald-500">
                    <CheckCircle2 className="size-4" />
                     <span>{syncProgress.successCount} {adminT('admin.githubSync.succeeded')}</span>
                   </div>
                   {syncProgress.errorCount > 0 && (
                     <div className="flex items-center gap-1.5 text-destructive">
                       <XCircle className="size-4" />
                       <span>{syncProgress.errorCount} {adminT('admin.githubSync.failed')}</span>
                     </div>
                   )}
                </div>
              )}
              {syncFinished && syncProgress.errors.length > 0 && (
                <div className="bg-destructive/10 border border-destructive/30 rounded-sm p-3 text-xs space-y-1">
                   <p className="font-medium text-destructive">{adminT('admin.githubSync.failedModules')}</p>
                  <ul className="list-disc list-inside text-muted-foreground space-y-0.5">
                    {syncProgress.errors.map((e, idx) => (
                      <li key={idx}>{e.label} — {e.message}</li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          ) : (
             <p className="text-sm text-muted-foreground">
               {adminT('admin.githubSync.moduleCount')}
             </p>
          )}

          {/* 部署状态提示 */}
          {syncFinished && syncProgress && syncProgress.successCount > 0 && (
            <div className="border border-primary/30 bg-primary/5 rounded-sm p-4 space-y-3">
              <div className="flex items-center gap-2 text-primary font-medium">
                <Sparkles className="size-4" />
                 {adminT('admin.githubSync.deploymentInProgress')}
               </div>
              <div className="space-y-2 text-sm text-muted-foreground">
                <div className="flex items-center gap-2">
                  <CheckCircle2 className="size-4 text-emerald-500 shrink-0" />
                   <span>{adminT('admin.githubSync.committed')}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Loader2 className="size-4 text-primary shrink-0 animate-spin" />
                   <span>{adminT('admin.githubSync.deploying')}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Clock className="size-4 text-muted-foreground shrink-0" />
                   <span>{adminT('admin.githubSync.deployedNote')}</span>
                </div>
              </div>
              {config.owner && config.repo && (
                <UniversalLink
                   to={`https://github.com/${config.owner}/${config.repo}/actions`}
                  target="_blank"
                  rel="noreferrer"
                  className="text-xs text-primary hover:underline inline-flex items-center gap-1"
                >
                   {adminT('admin.githubSync.viewOnActions')}
                   <ExternalLink className="size-3" />
                </UniversalLink>
              )}
               <p className="text-xs text-muted-foreground">
                 {adminT('admin.githubSync.refreshTip')}
               </p>
            </div>
          )}
        </CardContent>
        <CardFooter>
          <Button
            onClick={async () => {
              setSyncProgress({
                currentIndex: 0,
                total: 0,
                currentLabel: adminT('admin.githubSync.preparing'),
                successCount: 0,
                errorCount: 0,
                errors: [],
                isSyncing: true,
              });
              setSyncFinished(false);
              await syncAll({
                onProgress: (p) => setSyncProgress(p),
                onComplete: () => setSyncFinished(true),
              });
            }}
            disabled={syncProgress?.isSyncing || !config.enabled || (!config.token && !config.workerUrl) || !config.owner || !config.repo}
            className="w-full"
          >
            {syncProgress?.isSyncing ? (
              <>
                <Loader2 className="size-4 mr-2 animate-spin" />
                 {adminT('admin.githubSync.syncing')} ({syncProgress.currentIndex}/{syncProgress.total})
               </>
             ) : (
               <>
                 <UploadCloud className="size-4 mr-2" />
                 {adminT('admin.githubSync.syncEntireSite')}
               </>
            )}
          </Button>
        </CardFooter>
      </Card>

      {/* 从 GitHub 拉取数据 */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ArrowDownToLine className="size-5" />
            Pull Data from GitHub
          </CardTitle>
          <CardDescription>
            Fetch the latest data files from your GitHub repository and update local data.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {pullData.isPulling || pullData.lastPullTime ? (
            <div className="space-y-3">
              <div className="flex items-center justify-between text-sm">
                <span className="text-foreground font-medium">
                  {pullData.isPulling ? 'Pulling from GitHub...' : 'Pull completed'}
                </span>
                <span className="text-muted-foreground tabular-nums">
                  {pullData.successCount + pullData.failCount} / {Object.keys(pullData.modules).length || 11}
                </span>
              </div>
              {/* 进度条 */}
              <div className="w-full h-2 bg-border rounded-full overflow-hidden">
                <div
                  className="h-full bg-emerald-500 transition-all duration-300 ease-out"
                  style={{
                    width: `${
                      pullData.isPulling && Object.keys(pullData.modules).length > 0
                        ? ((pullData.successCount + pullData.failCount) / Object.keys(pullData.modules).length) * 100
                        : pullData.lastPullTime
                          ? 100
                          : 0
                    }%`,
                  }}
                />
              </div>
              {/* 当前拉取中模块 */}
              {pullData.isPulling && (
                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                  <Loader2 className="size-4 animate-spin text-emerald-500" />
                  <span>Fetching data from repository...</span>
                </div>
              )}
              {/* 完成统计 */}
              {pullData.lastPullTime && !pullData.isPulling && (
                <div className="space-y-3 pt-2">
                  <div className="flex flex-wrap gap-4 text-sm">
                    <div className="flex items-center gap-1.5 text-emerald-500">
                      <CheckCircle2 className="size-4" />
                      <span>{pullData.successCount} succeeded</span>
                    </div>
                    {pullData.skipCount > 0 && (
                      <div className="flex items-center gap-1.5 text-muted-foreground">
                        <MinusCircle className="size-4" />
                        <span>{pullData.skipCount} skipped</span>
                      </div>
                    )}
                    {pullData.failCount > 0 && (
                      <div className="flex items-center gap-1.5 text-destructive">
                        <XCircle className="size-4" />
                        <span>{pullData.failCount} failed</span>
                      </div>
                    )}
                  </div>

                  {/* 模块状态详情 */}
                  <div className="pt-2 border-t border-border/50">
                    <p className="text-xs text-muted-foreground mb-2">Module details</p>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-1.5 text-xs">
                      {Object.entries(pullData.modules).map(([mod, state]) => (
                        <div
                          key={mod}
                          className={cn(
                            'flex items-center gap-1.5 px-2 py-1 rounded-sm',
                            state === 'success' && 'text-emerald-500 bg-emerald-500/10',
                            state === 'skipped' && 'text-muted-foreground bg-muted/50',
                            state === 'failed' && 'text-destructive bg-destructive/10',
                            state === 'pulling' && 'text-info bg-info/10',
                          )}
                        >
                          {state === 'success' && <CheckCircle2 className="size-3 shrink-0" />}
                          {state === 'skipped' && <MinusCircle className="size-3 shrink-0" />}
                          {state === 'failed' && <XCircle className="size-3 shrink-0" />}
                          {state === 'pulling' && <Loader2 className="size-3 shrink-0 animate-spin" />}
                          <span className="truncate capitalize">{mod}</span>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* skipped 说明 */}
                  {pullData.skipCount > 0 && (
                    <p className="text-xs text-muted-foreground leading-relaxed">
                      <span className="text-amber-500 font-medium">Note:</span>{' '}
                      Skipped modules have no data file on GitHub yet. This is normal on first sync —
                      the files will be created when you save data in the corresponding admin page
                      and push to GitHub.
                    </p>
                  )}

                  {/* 失败详情 */}
                  {pullData.failedModules && pullData.failedModules.length > 0 && (
                    <div className="pt-2 border-t border-border/50 space-y-1">
                      <p className="text-xs font-medium text-destructive">Errors</p>
                      {pullData.failedModules.map((f, i) => (
                        <p key={i} className="text-xs text-muted-foreground">
                          <span className="text-destructive font-medium">{f.module}:</span> {f.message}
                        </p>
                      ))}
                    </div>
                  )}
                </div>
              )}
            </div>
          ) : (
            <p className="text-sm text-muted-foreground">
              Pull {Object.keys(DATA_FILES).length} data modules from GitHub to sync with the latest content.
            </p>
          )}
        </CardContent>
        <CardFooter>
          <Button
            onClick={async () => {
              await pullData.pullAllData();
            }}
            disabled={pullData.isPulling || !config.enabled || (!config.token && !config.workerUrl) || !config.owner || !config.repo}
            variant="secondary"
            className="w-full"
          >
            {pullData.isPulling ? (
              <>
                <Loader2 className="size-4 mr-2 animate-spin" />
                Pulling from GitHub...
              </>
            ) : (
              <>
                <ArrowDownToLine className="size-4 mr-2" />
                Pull Data from GitHub
              </>
            )}
          </Button>
        </CardFooter>
      </Card>

      {/* Token 生成步骤说明 */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <HelpCircle className="size-5" />
             {adminT('admin.githubSync.howToCreateToken')}
           </CardTitle>
           <CardDescription>
             {adminT('admin.githubSync.howToCreateTokenDesc')}
           </CardDescription>
        </CardHeader>
        <CardContent>
          <Accordion type="single" collapsible className="w-full">
            <AccordionItem value="step1">
              <AccordionTrigger className="text-left">
                 {adminT('admin.githubSync.step1Title')}
               </AccordionTrigger>
               <AccordionContent className="text-sm text-muted-foreground space-y-2">
                 <p><UniversalLink to="https://github.com/settings/tokens?type=beta" target="_blank" rel="noreferrer" className="text-primary underline inline-flex items-center">
                   GitHub Fine-grained Tokens <ExternalLink className="size-3 ml-1" />
                 </UniversalLink></p>
                 <p>{adminT('admin.githubSync.step1Text')}</p>
               </AccordionContent>
            </AccordionItem>
            <AccordionItem value="step2">
              <AccordionTrigger className="text-left">
                 {adminT('admin.githubSync.step2Title')}
               </AccordionTrigger>
               <AccordionContent className="text-sm text-muted-foreground space-y-2">
                 <ul className="list-disc list-inside space-y-1">
                   <li>{adminT('admin.githubSync.step2Name')}</li>
                   <li>{adminT('admin.githubSync.step2Expiration')}</li>
                   <li>{adminT('admin.githubSync.step2RepoAccess')}</li>
                 </ul>
               </AccordionContent>
            </AccordionItem>
            <AccordionItem value="step3">
              <AccordionTrigger className="text-left">
                 {adminT('admin.githubSync.step3Title')}
               </AccordionTrigger>
               <AccordionContent className="text-sm text-muted-foreground space-y-2">
                 <ul className="list-disc list-inside space-y-1">
                   <li><strong>{adminT('admin.githubSync.step3Permission')}</strong></li>
                 </ul>
                 <p className="mt-2">{adminT('admin.githubSync.step3OtherPerm')}</p>
               </AccordionContent>
            </AccordionItem>
            <AccordionItem value="step4">
              <AccordionTrigger className="text-left">
                 {adminT('admin.githubSync.step4Title')}
               </AccordionTrigger>
               <AccordionContent className="text-sm text-muted-foreground space-y-2">
                 <p>{adminT('admin.githubSync.step4Copy')}</p>
                 <p>{adminT('admin.githubSync.step4Paste')}</p>
               </AccordionContent>
            </AccordionItem>
            <AccordionItem value="step5">
              <AccordionTrigger className="text-left">
                 {adminT('admin.githubSync.step5Title')}
               </AccordionTrigger>
               <AccordionContent className="text-sm text-muted-foreground space-y-2">
                 <ol className="list-decimal list-inside space-y-1">
                   <li>{adminT('admin.githubSync.step5GoTo')}</li>
                   <li>{adminT('admin.githubSync.step5Source')}</li>
                   <li>{adminT('admin.githubSync.step5Branch')}</li>
                   <li>{adminT('admin.githubSync.step5Save')}</li>
                 </ol>
               </AccordionContent>
            </AccordionItem>
          </Accordion>
        </CardContent>
      </Card>

      {/* Issue 创建测试结果 */}
      {issueTestResult && (
        <Card className={
          issueTestResult.success
            ? 'border-emerald-500/30 bg-emerald-500/5'
            : 'border-destructive/30 bg-destructive/5'
        }>
          <CardContent className="pt-6">
            <div className="flex items-start gap-3">
              {issueTestResult.success ? (
                <CheckCircle2 className="size-6 text-emerald-500 shrink-0 mt-0.5" />
              ) : (
                <XCircle className="size-6 text-destructive shrink-0 mt-0.5" />
              )}
              <div className="space-y-2 text-sm">
                <p className="font-medium text-foreground">
                  {issueTestResult.success ? 'Issue Creation Test Passed' : 'Issue Creation Test Failed'}
                </p>
                <p className="text-muted-foreground">{issueTestResult.message}</p>
                {issueTestResult.issueUrl && (
                  <UniversalLink
                    to={issueTestResult.issueUrl}
                    target="_blank"
                    rel="noreferrer"
                    className="text-primary hover:underline inline-flex items-center gap-1 text-xs"
                  >
                    View on GitHub <ExternalLink className="size-3" />
                  </UniversalLink>
                )}
                {!issueTestResult.success && (
                  <div className="pt-2 space-y-1 text-xs text-muted-foreground">
                    <p className="font-medium text-foreground">Common causes:</p>
                    <ul className="list-disc list-inside space-y-0.5">
                      <li>Token does not have <strong>Issues: Read and write</strong> permission</li>
                      <li>Token is expired or has been revoked</li>
                      <li>Repository name or owner is incorrect</li>
                      <li>Repository is private and token has no access</li>
                    </ul>
                  </div>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* GitHub Issues 询盘邮件通知说明 */}
      <Card className="border-primary/30 bg-primary/5">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-foreground">
            <Mail className="size-5 text-primary" />
            Inquiry Email Notifications via GitHub Issues
          </CardTitle>
          <CardDescription>
            Customer inquiries are automatically created as GitHub Issues, triggering email notifications via GitHub Actions.
          </CardDescription>
        </CardHeader>
        <CardContent className="text-sm space-y-4 text-muted-foreground">
          <p>
            When a visitor submits an inquiry form on your website, the system automatically creates a GitHub Issue in your configured repository with the <Badge variant="outline" className="text-xs border-primary/40 text-primary mx-1">inquiry</Badge> label.
            GitHub Actions then sends you an email notification with the full inquiry details.
          </p>

          <Accordion type="single" collapsible className="w-full">
            <AccordionItem value="setup">
              <AccordionTrigger className="text-foreground font-medium">
                Setup Guide (5 Steps)
              </AccordionTrigger>
              <AccordionContent className="space-y-3 pt-2">
                <ol className="list-decimal list-inside space-y-2">
                  <li>
                    <strong className="text-foreground">Ensure Issues permission</strong>
                    <p className="pl-5">Your GitHub Personal Access Token must have <strong>Issues: Read and write</strong> permission. Use the "Test Issue Creation" button above to verify.</p>
                  </li>
                  <li>
                    <strong className="text-foreground">Push the workflow file to your repository</strong>
                    <p className="pl-5">The <code className="bg-background px-1.5 py-0.5 rounded">.github/workflows/inquiry-notification.yml</code> file is automatically included when you run "Sync Entire Site". Run a full site sync to push it to your repo, or upload it manually.</p>
                    <p className="pl-5 text-xs">
                      <UniversalLink
                        to={`https://github.com/${config.owner}/${config.repo}/blob/${config.branch}/.github/workflows/inquiry-notification.yml`}
                        target="_blank"
                        rel="noreferrer"
                        className="text-primary hover:underline inline-flex items-center gap-1"
                      >
                        Check if workflow file exists in your repo <ExternalLink className="size-3" />
                      </UniversalLink>
                    </p>
                  </li>
                  <li>
                    <strong className="text-foreground">Configure SMTP Secrets</strong>
                    <p className="pl-5">In your GitHub repository, go to <strong>Settings → Secrets and variables → Actions → New repository secret</strong> and add these secrets:</p>
                    <div className="pl-8 grid grid-cols-2 gap-x-4 gap-y-1 text-xs mt-1">
                      <div><code>SMTP_SERVER</code> — e.g. <code>smtp.gmail.com</code></div>
                      <div><code>SMTP_PORT</code> — e.g. <code>465</code></div>
                      <div><code>SMTP_USERNAME</code> — your email</div>
                      <div><code>SMTP_PASSWORD</code> — app password</div>
                      <div><code>NOTIFY_EMAIL</code> — recipient email</div>
                      <div><code>SENDER_EMAIL</code> — optional</div>
                    </div>
                  </li>
                  <li>
                    <strong className="text-foreground">Enable GitHub Actions</strong>
                    <p className="pl-5">Go to <strong>Settings → Actions → General</strong> and make sure "Allow all actions and reusable workflows" is enabled.</p>
                  </li>
                  <li>
                    <strong className="text-foreground">Test it</strong>
                    <p className="pl-5">Click "Test Issue Creation" above — it will create an Issue titled <code>[Inquiry] [Test] ...</code>, which triggers the workflow. Check your email inbox.</p>
                  </li>
                </ol>
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="gmail">
              <AccordionTrigger className="text-foreground font-medium">
                Gmail / Google Workspace Setup
              </AccordionTrigger>
              <AccordionContent className="space-y-2 pt-2 text-sm">
                <p>Gmail requires an <strong>App Password</strong>, NOT your regular password:</p>
                <ol className="list-decimal list-inside space-y-1 pl-2">
                  <li>Enable <strong>2-Step Verification</strong> on your Google account</li>
                  <li>Go to <UniversalLink to="https://myaccount.google.com/apppasswords" target="_blank" rel="noreferrer" className="text-primary hover:underline">myaccount.google.com/apppasswords <ExternalLink className="size-3" /></UniversalLink></li>
                  <li>Create a new app password (select "Mail" app, "Other" device)</li>
                  <li>Copy the 16-character code and paste it as <code>SMTP_PASSWORD</code></li>
                </ol>
                <div className="mt-2 space-y-1">
                  <p className="font-medium text-foreground">Gmail Recommended Settings:</p>
                  <ul className="list-disc list-inside pl-2 space-y-0.5">
                    <li><code>SMTP_SERVER</code> = <code>smtp.gmail.com</code></li>
                    <li><code>SMTP_PORT</code> = <code>465</code> (SSL/TLS)</li>
                    <li><code>SMTP_USERNAME</code> = your full Gmail address</li>
                    <li><code>SENDER_EMAIL</code> = same as SMTP_USERNAME</li>
                  </ul>
                </div>
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="troubleshoot">
              <AccordionTrigger className="text-foreground font-medium">
                Troubleshooting: Not Receiving Emails?
              </AccordionTrigger>
              <AccordionContent className="space-y-3 pt-2 text-sm">
                <p className="font-medium text-foreground">Step 1: Check if the Issue was created</p>
                <ul className="list-disc list-inside pl-2 space-y-0.5">
                  <li>Go to your GitHub repo → Issues tab</li>
                  <li>Look for an Issue titled <code>[Inquiry] ...</code></li>
                  <li>If Issue exists → move to Step 2</li>
                  <li>If Issue does NOT exist → Token has no Issues permission, or wrong owner/repo</li>
                </ul>

                <p className="font-medium text-foreground mt-3">Step 2: Check if the workflow ran</p>
                <ul className="list-disc list-inside pl-2 space-y-0.5">
                  <li>Go to your repo → <strong>Actions</strong> tab</li>
                  <li>Look for "Inquiry Email Notification" workflow runs</li>
                  <li>If you see a run with green ✓ → email was sent (check spam folder)</li>
                  <li>If you see a run with red ✗ → click it, read the error, check Step 3</li>
                  <li>If there's NO run at all → workflow file not present or not triggered</li>
                </ul>

                <p className="font-medium text-foreground mt-3">Step 3: Common errors and fixes</p>
                <div className="space-y-2 pl-2">
                  <div className="bg-card/50 p-2 rounded-sm">
                    <p className="text-destructive font-medium">❌ "Missing required secrets: SMTP_..."</p>
                    <p className="text-xs">You haven't added the SMTP secrets. Go to Settings → Secrets and variables → Actions.</p>
                  </div>
                  <div className="bg-card/50 p-2 rounded-sm">
                    <p className="text-destructive font-medium">❌ "535-5.7.8 Username and Password not accepted"</p>
                    <p className="text-xs">Gmail rejected your password. You need to use an App Password, not your regular password. See "Gmail Setup" tab.</p>
                  </div>
                  <div className="bg-card/50 p-2 rounded-sm">
                    <p className="text-destructive font-medium">❌ "getaddrinfo ENOTFOUND" or connection error</p>
                    <p className="text-xs">SMTP_SERVER address is wrong or unreachable. Double-check the server address and port.</p>
                  </div>
                  <div className="bg-card/50 p-2 rounded-sm">
                    <p className="text-destructive font-medium">❌ No workflow run at all</p>
                    <p className="text-xs">Either the workflow file is not in the repo, or GitHub Actions is disabled. Run "Sync Entire Site" to push the workflow file.</p>
                  </div>
                  <div className="bg-card/50 p-2 rounded-sm">
                    <p className="text-destructive font-medium">❌ Workflow ran successfully but no email received</p>
                    <p className="text-xs">Check your spam/junk folder. Also verify NOTIFY_EMAIL is correct.</p>
                  </div>
                </div>

                <p className="font-medium text-foreground mt-3">Step 4: Verify workflow file</p>
                <p className="pl-2">The workflow file must be at this exact path:</p>
                <p className="pl-4"><code>.github/workflows/inquiry-notification.yml</code></p>
                <p className="pl-2 text-xs">Run "Sync Entire Site" to automatically upload it.</p>
              </AccordionContent>
            </AccordionItem>

            <AccordionItem value="howitworks">
              <AccordionTrigger className="text-foreground font-medium">
                How It Works (Diagram)
              </AccordionTrigger>
              <AccordionContent className="pt-2 text-sm space-y-2">
                <div className="space-y-2 font-mono text-xs bg-card/50 p-3 rounded-sm">
                  <p>1️⃣ Customer submits inquiry form on website</p>
                  <p className="pl-4">↓</p>
                  <p>2️⃣ Frontend saves inquiry to localStorage</p>
                  <p className="pl-4">↓</p>
                  <p>3️⃣ Frontend calls GitHub API → creates Issue with title "[Inquiry] ..."</p>
                  <p className="pl-4">↓</p>
                  <p>4️⃣ GitHub detects new Issue → triggers Actions workflow</p>
                  <p className="pl-4">↓</p>
                  <p>5️⃣ Workflow runs dawidd6/action-send-mail → sends SMTP email</p>
                  <p className="pl-4">↓</p>
                  <p>6️⃣ You receive inquiry details in your email inbox 📧</p>
                </div>
              </AccordionContent>
            </AccordionItem>
          </Accordion>

          <p className="pt-2 text-xs">
            <strong>Note:</strong> Issue creation is silent and non-blocking — if GitHub is unavailable or not configured, the inquiry is still saved locally without affecting the user experience.
          </p>
        </CardContent>
      </Card>

      {/* 安全提示 */}
      <Card className="border-amber-500/30 bg-amber-500/5">
        <CardHeader>
          <CardTitle className="text-amber-600 dark:text-amber-500 flex items-center gap-2">
            <AlertTriangle className="size-5" />
             {adminT('admin.githubSync.securityNotes')}
           </CardTitle>
         </CardHeader>
         <CardContent className="text-sm space-y-2">
           <ul className="list-disc list-inside space-y-1 text-muted-foreground">
             <li>{adminT('admin.githubSync.securityLocalOnly')}</li>
             <li>{adminT('admin.githubSync.securityNoServer')}</li>
             <li>{adminT('admin.githubSync.securityNotCommitted')}</li>
             <li>{adminT('admin.githubSync.securityMinPerm')}</li>
             <li>{adminT('admin.githubSync.securityLogout')}</li>
           </ul>
        </CardContent>
      </Card>
    </div>
  );
}
