/**
 * 深度合并两个翻译对象，**本地优先**：
 * - 本地有值的键：保留本地值（用户手动修改过，优先级更高）
 * - 本地没有、远端有值的键：用远端值补全（新增翻译键）
 *
 * 用于 Pull Data 时 translations 模块的合并，防止远端全量覆盖掉本地未同步的翻译修改。
 */
function deepMergeTranslationsLocalPriority(
  local: Record<string, unknown>,
  remote: Record<string, unknown>
): Record<string, unknown> {
  const result = { ...local };
  for (const key of Object.keys(remote)) {
    const localVal = result[key];
    const remoteVal = remote[key];
    const localIsObject =
      localVal != null && typeof localVal === 'object' && !Array.isArray(localVal);
    const remoteIsObject =
      remoteVal != null && typeof remoteVal === 'object' && !Array.isArray(remoteVal);

    if (localIsObject && remoteIsObject) {
      // 两端都是对象 → 递归合并（本地优先）
      result[key] = deepMergeTranslationsLocalPriority(
        localVal as Record<string, unknown>,
        remoteVal as Record<string, unknown>
      );
    } else if (typeof localVal === 'string') {
      // 本地已有字符串值 → 保留（本地优先）
      result[key] = localVal;
    } else if (remoteIsObject) {
      // 本地没有（或不是对象）、远端有嵌套对象 → 直接补全整个对象
      // 🔴 修复：之前漏掉了这个分支，导致深层嵌套翻译全部丢失
      result[key] = remoteVal;
    } else if (typeof remoteVal === 'string') {
      // 本地没有、远端有字符串 → 补全
      result[key] = remoteVal;
    }
  }
  return result;
}

