export interface PullStatus {
  isPulling: boolean;
  lastPullTime: number | null;
  successCount: number;
  failCount: number;
  errorMessage: string;
  modules: Record<string, 'pending' | 'pulling' | 'success' | 'failed' | 'skipped'>;
  skipCount: number;
  failedModules: { module: string; message: string }[];
}

const INITIAL_STATUS: PullStatus = {
  isPulling: false,
  lastPullTime: null,
  successCount: 0,
  failCount: 0,
  skipCount: 0,
  errorMessage: '',
  modules: {},
  failedModules: [],
};

/**
 * 从 GitHub 拉取单个 JSON 文件
 */
async function fetchJsonFile(
  config: GithubConfig,
  path: string
): Promise<{ data: unknown; sha: string | null; notFound: boolean }> {
  const fullPath = resolveGithubPath(config.basePath, path);
  const file = await getFileContent(config, fullPath);
  // 文件不存在（404 / 是目录）→ notFound=true，上层标记为 skipped
  if (!file) {
    return { data: null, sha: null, notFound: true };
  }
  // 文件存在但内容为空（空文件）→ 也算 notFound
  if (!file.content) {
    return { data: null, sha: file.sha ?? null, notFound: true };
  }
  const decoded = decodeBase64Content(file.content);
  const data = JSON.parse(decoded);
  return { data, sha: file.sha ?? null, notFound: false };
}

/**
 * 保存数据到 localStorage（适配各模块的存储格式）
 */
function saveToLocalStorage(module: string, data: unknown): void {
  const keyMap: Record<string, string> = {
    advantages: '__app_ledlight_advantages_v3',
    testimonials: '__app_ledlight_testimonials_v3',
    features: '__app_ledlight_features_v2',
    heroSlides: '__app_ledlight_hero_slides',
    about: '__app_ledlight_about_content_v1',
    news: '__app_ledlight_articles_v3',
    categories: '__app_ledlight_categories_v1',
    footer: '__app_ledlight_footer_settings',
    seo: '__app_ledlight_seo_settings',
    privacy: '__app_ledlight_privacy_policy_v1',
    settings: '__app_ledlight_admin_password',
    inquiries: '__app_ledlight_inquiries',
    translations: '__app_ledlight_custom_translations',
    faqs: '__app_ledlight_faqs_v1',
    quoteSection: '__app_ledlight_quote_section_v1',
    blog: '__app_ledlight_blog_articles_v1',
  };

  const storageKey = keyMap[module];
  if (!storageKey) return;

  const version = STORAGE_VERSION_MAP[module] ?? 1;

  // 产品模块特殊：走 IndexedDB，不在这处理
  if (module === 'products') return;

  // settings 模块特殊：adminPassword + analytics/translation/githubSync 子对象分别存
  // 管理员密码从远端同步回写（加密存储，解密后存入本地），实现跨浏览器密码一致
  // 部署包升级后密码也不会还原
  if (module === 'settings') {
    if (data && typeof data === 'object' && !Array.isArray(data)) {
      const obj = data as Record<string, unknown>;
      // 管理员密码：从远端同步回写（加密存储，需解密）
      // 🔴 重要：如果本地已有非默认密码（用户改过），不被远程覆盖
      if (obj.adminPassword && typeof obj.adminPassword === 'string' && obj.adminPassword.length >= 6) {
        try {
          // 先检查本地密码是否已被用户修改
          let localPwd = 'admin123';
          try {
            const saved = localStorage.getItem('__app_ledlight_admin_password');
            if (saved && typeof saved === 'string' && saved.length >= 6) {
              localPwd = saved;
            }
          } catch {
            // ignore
          }

          const decrypted = decryptPassword(obj.adminPassword);
          const remotePwd = decrypted && decrypted.length >= 6 ? decrypted : obj.adminPassword;

          // 只有当本地是默认密码时，才用远程密码覆盖
          // 用户已修改过的密码永久保留，不被远程/部署包还原
          if (localPwd === 'admin123') {
            localStorage.setItem('__app_ledlight_admin_password', remotePwd);
            logger.info(`[GitHub Pull] Saved admin password from settings (local was default, now synced)`);
          } else {
            logger.info(`[GitHub Pull] Skipped password overwrite — local password is customized, preserving user change`);
          }
        } catch (e) {
          logger.warn(`[GitHub Pull] Failed to save admin password:`, String(e));
        }
      }
      // 分析设置（全量同步，无敏感字段）
      if (obj.analytics && typeof obj.analytics === 'object') {
        try {
          const analyticsKey = '__app_ledlight_analytics_settings';
          localStorage.setItem(analyticsKey, JSON.stringify(obj.analytics));
          logger.info(`[GitHub Pull] Saved analytics settings from settings`);
        } catch (e) {
          logger.warn(`[GitHub Pull] Failed to save analytics settings:`, String(e));
        }
      }
      // 翻译设置：合并非敏感字段，保留本地 API Key 等敏感字段
      if (obj.translation && typeof obj.translation === 'object') {
        try {
          const translateKey = '__app_ledlight_translate_settings';
          const remote = obj.translation as Record<string, unknown>;
          const savedLocal = localStorage.getItem(translateKey);
          const local = savedLocal ? JSON.parse(savedLocal) : {};
          const merged = {
            ...local,
            provider: (remote.provider as string) ?? local.provider ?? 'mymemory',
            deeplPlan: (remote.deeplPlan as string) ?? local.deeplPlan ?? 'free',
            useCorsProxy: typeof remote.useCorsProxy === 'boolean' ? remote.useCorsProxy : (local.useCorsProxy ?? true),
            customProxyUrl: typeof remote.customProxyUrl === 'string' ? remote.customProxyUrl : (local.customProxyUrl ?? ''),
            // 敏感字段：保留本地值，不从远端覆盖
            deeplApiKey: local.deeplApiKey ?? '',
            corsProxyApiKey: local.corsProxyApiKey ?? '',
          };
          localStorage.setItem(translateKey, JSON.stringify(merged));
          // 触发同 tab 内刷新事件
          try {
            window.dispatchEvent(
              new CustomEvent('translate-settings-change', { detail: merged })
            );
          } catch {
            /* ignore */
          }
          logger.info(`[GitHub Pull] Saved translation settings from settings (non-sensitive fields merged)`);
        } catch (e) {
          logger.warn(`[GitHub Pull] Failed to save translation settings:`, String(e));
        }
      }
      // GitHub 同步配置：合并非敏感字段，保留本地 token
      if (obj.githubSync && typeof obj.githubSync === 'object') {
        try {
          const githubKey = '__app_ledlight_github_config_v1';
          const remote = obj.githubSync as Record<string, unknown>;
          const savedLocal = localStorage.getItem(githubKey);
          const local = savedLocal ? JSON.parse(savedLocal) : {};
          const merged = {
            ...local,
            owner: typeof remote.owner === 'string' ? remote.owner : (local.owner ?? ''),
            repo: typeof remote.repo === 'string' ? remote.repo : (local.repo ?? ''),
            branch: typeof remote.branch === 'string' ? remote.branch : (local.branch ?? 'main'),
            basePath: typeof remote.basePath === 'string' ? remote.basePath : (local.basePath ?? ''),
            enabled: typeof remote.enabled === 'boolean' ? remote.enabled : (local.enabled ?? false),
            // 敏感字段：保留本地值，不从远端覆盖
            token: local.token ?? '',
          };
          localStorage.setItem(githubKey, JSON.stringify(merged));
          // 触发同 tab 内刷新事件
          try {
            window.dispatchEvent(
              new CustomEvent('github-config-change', { detail: merged })
            );
          } catch {
            /* ignore */
          }
          logger.info(`[GitHub Pull] Saved GitHub sync config from settings (non-sensitive fields merged)`);
        } catch (e) {
          logger.warn(`[GitHub Pull] Failed to save GitHub config:`, String(e));
        }
      }
    }
    return;
  }

  // translations 模块特殊：与本地自定义翻译深度合并（本地优先）后存入 custom translations key
  // 🔴 关键修复：之前直接用远端全量覆盖本地，用户未同步的翻译修改会全部丢失。
  // 现在合并策略：以本地 customTranslations 为基础，只把远端**新增的**字段补进来，
  // 本地已有的字段一律保留（用户改过的内容不能被远端覆盖）。
  if (module === 'translations') {
    if (data && typeof data === 'object' && !Array.isArray(data)) {
      let savedLocal: Record<string, unknown> = {};
      try {
        const raw = localStorage.getItem(storageKey);
        if (raw) savedLocal = JSON.parse(raw) as Record<string, unknown>;
      } catch {
        savedLocal = {};
      }

      const merged = deepMergeTranslationsLocalPriority(
        savedLocal,
        data as Record<string, unknown>
      );
      localStorage.setItem(storageKey, JSON.stringify(merged));
      // 触发同 tab 内 i18n 刷新
      try {
        window.dispatchEvent(
          new CustomEvent('custom-translations-change', { detail: merged })
        );
      } catch {
        /* ignore */
      }
      logger.info(`[GitHub Pull] Merged translations (local priority), saved successfully`);
    }
    return;
  }

  // footer 模块特殊：直接存裸 FooterSettings 对象（不加 __version 包装）
  // FooterSettingsContext 读取时直接 JSON.parse 成 Partial<FooterSettings>，格式必须一致
  if (module === 'footer') {
    if (data && typeof data === 'object' && !Array.isArray(data)) {
      localStorage.setItem(storageKey, JSON.stringify(data));
      // 触发同 tab 内刷新（storage 事件只在其他 tab 触发）
      try {
        window.dispatchEvent(
          new CustomEvent('footer-settings-change', { detail: data })
        );
      } catch {
        /* ignore */
      }
      logger.info(`[GitHub Pull] Saved footer settings`);
    }
    return;
  }

  // inquiries 模块特殊：直接存 IInquiry[] 数组（不加 __version 包装）
  // InquiryContext 的 loadInquiries 读取时直接 JSON.parse 成数组，格式必须一致
  if (module === 'inquiries') {
    if (Array.isArray(data)) {
      localStorage.setItem(storageKey, JSON.stringify(data));
      // 触发同 tab 内刷新
      try {
        window.dispatchEvent(new CustomEvent('__app_ledlight_inquiry_sync__'));
      } catch {
        /* ignore */
      }
      logger.info(`[GitHub Pull] Saved ${data.length} inquiries`);
    }
    return;
  }

  // seo 模块特殊：直接存裸 SeoSettings 对象（不加 __version 包装）
  // useSeoSettings 读取时直接 JSON.parse 成 SeoSettings，格式必须一致
  if (module === 'seo') {
    if (data && typeof data === 'object' && !Array.isArray(data)) {
      localStorage.setItem(storageKey, JSON.stringify(data));
      // 触发同 tab 内刷新
      try {
        window.dispatchEvent(
          new CustomEvent('seo-settings-change', { detail: data })
        );
      } catch {
        /* ignore */
      }
      logger.info(`[GitHub Pull] Saved seo settings`);
    }
    return;
  }

  // factoryVideo 模块特殊：设置存 scopedStorage，视频文件存 IndexedDB
  // 这里只处理 JSON 配置（开关、标题、URL 等），视频文件本身由 useSiteWideSync 同步
  if (module === 'factoryVideo') {
    if (data && typeof data === 'object' && !Array.isArray(data)) {
      try {
        scopedStorage.setItem(
          '__app_ledlight_factory_video_settings',
          JSON.stringify({ __version: 1, data })
        );
        // 触发同 tab 内刷新事件
        window.dispatchEvent(new CustomEvent('factory-video-settings-change', { detail: data }));
        logger.info(`[GitHub Pull] Saved factory video settings`);
      } catch (e) {
        logger.warn(`[GitHub Pull] Failed to save factory video settings:`, String(e));
      }
    }
    return;
  }

  try {
    // Features 模块特殊：JSON 顶层是 { features: [...], sectionImage: '...' }
    // 需要提取 features 数组作为 data，sectionImage 存入 __sectionImage
    let payloadData = data;
    let extraFields: Record<string, unknown> = {};
    if (module === 'features' && data && typeof data === 'object' && !Array.isArray(data)) {
      const obj = data as Record<string, unknown>;
      if (Array.isArray(obj.features)) {
        payloadData = obj.features;
      }
      if (typeof obj.sectionImage === 'string') {
        extraFields.__sectionImage = obj.sectionImage;
      }
    }

    // Testimonials 模块特殊：JSON 顶层是 { showOnHomepage: boolean, data: [...] }
    // 老格式是纯数组，新格式是对象包装，两种都兼容
    if (module === 'testimonials' && data && typeof data === 'object' && !Array.isArray(data)) {
      const obj = data as Record<string, unknown>;
      if (Array.isArray(obj.data)) {
        payloadData = obj.data;
      }
      if (typeof obj.showOnHomepage === 'boolean') {
        extraFields.showOnHomepage = obj.showOnHomepage;
      }
    }

    // 带 __version 包装的格式
    const payload = { __version: version, data: payloadData, ...extraFields };
    localStorage.setItem(storageKey, JSON.stringify(payload));
    logger.info(`[GitHub Pull] Saved ${module} to localStorage (key=${storageKey})`);
  } catch (err) {
    logger.error(`[GitHub Pull] Failed to save ${module} to localStorage:`, String(err));
    throw err;
  }
}

/**
 * 触发各模块的数据刷新事件
 * 通过 window CustomEvent + 各模块的 subscriber 机制
 */
function triggerModuleRefresh(module: string, data: unknown): void {
  const eventMap: Record<string, string> = {
    products: 'app-ledlight-products-changed-v3',
    categories: 'app-ledlight-categories-changed-v1',
    news: 'app-ledlight-news-articles-changed-v3',
    blog: 'app-ledlight-blog-articles-changed-v1',
    quoteSection: 'app-ledlight-quote-section-github-pulled',
  };

  const eventName = eventMap[module];
  if (eventName) {
    try {
      const ev = new CustomEvent(eventName, { detail: data });
      window.dispatchEvent(ev);
      logger.info(`[GitHub Pull] Dispatched refresh event for ${module}`);
    } catch (err) {
      logger.warn(`[GitHub Pull] Failed to dispatch event for ${module}:`, String(err));
    }
  }
}

/**
 * 保存产品数据到 IndexedDB（整体替换）
 */
async function saveProductsToIndexedDB(products: unknown[]): Promise<void> {
  // 动态 import 避免 SSR 问题
  const { clearAllProducts, addProductsBatch } = await import('@/lib/indexed-db');
  // 注意：GitHub 上存储的产品数据格式需要和 IProduct 兼容
  // addProductsBatch 使用 put，类型上宽松处理（运行时结构一致即可）
  await clearAllProducts();
  await addProductsBatch(products as Parameters<typeof addProductsBatch>[0]);
  logger.info(`[GitHub Pull] Replaced ${products.length} products in IndexedDB`);
}

export function useGithubPullData() {
  const { getGithubApiConfig, isConfigured } = useGithubConfig();
  const remoteStore = useRemoteDataStoreFull();
  const [status, setStatus] = useState<PullStatus>(INITIAL_STATUS);
  const abortRef = useRef(false);

  /**
   * 从 GitHub 拉取所有数据模块并写入本地存储
   */
  const pullAllData = useCallback(async (): Promise<boolean> => {
    const config = getGithubApiConfig();
    if (!config) {
      logger.info('[GitHub Pull] GitHub not configured, skipping pull');
      return false;
    }

    if (abortRef.current) return false;

    setStatus((prev) => ({
      ...prev,
      isPulling: true,
      successCount: 0,
      failCount: 0,
      errorMessage: '',
      modules: {},
    }));

    let successCount = 0;
    let failCount = 0;
    let skipCount = 0;
    const failedModules: { module: string; message: string }[] = [];
    const moduleStatus: Record<string, 'pending' | 'pulling' | 'success' | 'failed' | 'skipped'> = {};

    const modules = Object.keys(DATA_FILES);

    for (const module of modules) {
      if (abortRef.current) break;

      moduleStatus[module] = 'pulling';
      setStatus((prev) => ({ ...prev, modules: { ...moduleStatus } }));

      try {
        const path = DATA_FILES[module];
        const { data, notFound } = await fetchJsonFile(config, path);

        // 文件不存在 → 跳过（首次同步时很常见，不算错误）
        if (notFound) {
          moduleStatus[module] = 'skipped';
          skipCount++;
          logger.info(`[GitHub Pull] ${module} skipped (file not found on GitHub, first sync?)`);
          setStatus((prev) => ({ ...prev, modules: { ...moduleStatus } }));
          continue;
        }

        // 写入本地存储
        if (module === 'products') {
          if (Array.isArray(data)) {
            await saveProductsToIndexedDB(data as unknown[]);
            // 同时也存一份到 localStorage 作为兜底镜像
            try {
              localStorage.setItem('__app_ledlight_products_v3', JSON.stringify(data));
            } catch {
              // localStorage 可能超限，忽略，IndexedDB 是主存储
            }
          } else {
            throw new Error('Products data is not an array');
          }
        } else {
          saveToLocalStorage(module, data);
        }

        // 🔴 同时更新 RemoteDataStore，让前台 preferRemote: true 的页面也能立即看到最新数据
        // 否则前台读的是 sessionStorage 里的旧缓存，Pull Data 对前台毫无作用
        if (remoteStore?.setModuleData && MODULE_TO_REMOTE[module]) {
          remoteStore.setModuleData(MODULE_TO_REMOTE[module] as RemoteDataModule, data);
        }

        // 触发模块刷新（让页面重新读取数据）
        triggerModuleRefresh(module, data);

        moduleStatus[module] = 'success';
        successCount++;
        logger.info(`[GitHub Pull] ${module} pulled successfully`);
      } catch (err) {
        moduleStatus[module] = 'failed';
        failCount++;
        const msg = err instanceof Error ? err.message : 'Unknown error';
        failedModules.push({ module, message: msg });
        logger.warn(`[GitHub Pull] Failed to pull ${module}: ${msg}`);
      }

      setStatus((prev) => ({ ...prev, modules: { ...moduleStatus } }));
    }

    // 额外刷新：products 和 categories 模块级 store 需要手动通知 subscriber
    // 因为它们的 state 存在模块级单例中，localStorage 变化不会自动触发重渲染
    try {
      await refreshModuleStores();
    } catch (err) {
      logger.warn('[GitHub Pull] Failed to refresh module stores:', String(err));
    }

    setStatus({
      isPulling: false,
      lastPullTime: Date.now(),
      successCount,
      failCount,
      skipCount,
      errorMessage: failCount > 0 ? `${failCount} module(s) failed to pull` : '',
      modules: moduleStatus,
      failedModules,
    });

    if (successCount > 0 && failCount === 0) {
      if (skipCount > 0) {
        toast.success(`${successCount} synced, ${skipCount} skipped (no data on GitHub)`);
      } else {
        toast.success(`Synced ${successCount} data modules from GitHub`);
      }
    } else if (successCount > 0 && failCount > 0) {
      toast.warning(`${successCount} synced, ${failCount} failed. Check details below.`);
    } else if (successCount === 0 && failCount === 0 && skipCount > 0) {
      toast.info(`No data to pull. All ${skipCount} modules skipped (files not found on GitHub).`);
    } else {
      toast.error('Failed to pull data from GitHub');
    }

    return failCount === 0;
  }, [getGithubApiConfig]);

  /**
   * 刷新各模块的 store（让页面重新读取最新数据）
   * 直接调用各模块暴露的 refreshXxxStore 函数
   */
  const refreshModuleStores = useCallback(async () => {
    // 产品模块：从 IndexedDB 重新读取
    try {
      const { refreshProductsStore } = await import('@/hooks/useProducts');
      refreshProductsStore();
    } catch (err) {
      logger.warn('[GitHub Pull] Failed to refresh products store:', String(err));
    }

    // 分类模块：从 localStorage 重新读取
    try {
      const { refreshCategoriesStore } = await import('@/hooks/useCategories');
      refreshCategoriesStore();
    } catch (err) {
      logger.warn('[GitHub Pull] Failed to refresh categories store:', String(err));
    }

    // 其他模块：发送自定义事件，各 hook 组件监听后自行重新读取
    // advantages, testimonials, features, heroSlides, about, news, footer, seo, privacy, faqs
    const otherModules = [
      'advantages', 'testimonials', 'features', 'heroSlides',
      'about', 'news', 'blog', 'footer', 'seo', 'privacy', 'settings', 'translations', 'faqs',
    ];
    for (const m of otherModules) {
      try {
        const ev = new CustomEvent(`app-ledlight-${m}-github-pulled`, {
          detail: { time: Date.now() },
        });
        window.dispatchEvent(ev);
      } catch { /* ignore */ }
    }

    logger.info('[GitHub Pull] All module stores refreshed');
  }, []);

  // 手动拉取（用户点击按钮时触发）
  const manualPull = useCallback(async () => {
    const config = getGithubApiConfig();
    if (!config) {
      toast.error('GitHub sync is not configured');
      return false;
    }
    return pullAllData();
  }, [getGithubApiConfig, pullAllData]);

  return {
    ...status,
    pullAllData: manualPull,
    isConfigured,
  };
}
